(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c69"]=[{"id":"00000913","register_sub_id":"101","register_pk":"132570","name":"青木家住宅土塀","kana":"あおきけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮前225","lat":34.04653257,"lng":134.00494964,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土塀，延長44m","structure_material":"土塀","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0016","desc":"屋敷地の北側（道路側）と東側の境を仕切る塀。下方を石積み，上方は屋敷側に控え壁を約１間おきに付けた形式で，道路側は漆喰仕上げ，東側はモルタル仕上げとする。道路側の頂部は斜めに並べた煉瓦の上に笠木を置き意匠に特段の工夫がほどこされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000913"},{"id":"00000911","register_sub_id":"101","register_pk":"101901","name":"青木家住宅納屋","kana":"あおきけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮前225","lat":34.0462701,"lng":134.0045627,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積40㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0014","desc":"主屋と倉庫の間に建つ切妻造，桟瓦葺，平屋建の建物。左右を土間の納屋，中央を便所とする。小規模で横長の簡素な建物だが，壁を鼠漆喰で仕上げ腰に板を貼ることによって主屋と意匠をあわせるなど，屋敷構えの景観によく溶け込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000911"},{"id":"00000912","register_sub_id":"101","register_pk":"101902","name":"青木家住宅門","kana":"あおきけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮前225","lat":34.0465144,"lng":134.004807,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造四脚門，瓦葺","structure_material":"木造四脚門","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0015","desc":"主屋の北方，道路に面して建つ四脚門。左右に塀が取り付く。本来は庭を通って主屋の座敷へと通じる裏側の門にあたるが，塀よりわずかに庭側に下がった所に位置し，道路側の屋根だけを本瓦で葺く（庭側は桟瓦）など意匠に工夫をこらして屋敷構えを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000912"},{"id":"00000914","register_sub_id":"101","register_pk":"132571","name":"青木家住宅煉瓦塀","kana":"あおきけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮前225","lat":34.04640617,"lng":134.00506638,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造，延長42m","structure_material":"煉瓦造","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0017","desc":"屋敷地南側境を仕切る塀。東方は屋敷への進入斜路にそって登る形で，西方は周辺より一段高い場所に位置する。約１間おきに控え壁がある点は土塀と似るが，形式はより簡略で控え壁を外側にみせる点は対照的。一部改造はあるが屋敷構えの主要な構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000914"},{"id":"00011413","register_sub_id":"101","register_pk":"209250","name":"内田家住宅蔵","kana":"うちだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町サラダ1731-1","lat":34.028364,"lng":133.811608,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積85㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0142","desc":"主屋の北側、敷地の西北隅に建ち、主屋と並んで妻面を見せる。土蔵造二階建で、腰部は板張とする。主屋に面した南側に下屋をかけ、扉口を開き、内部は一・二階とも東寄りを別室に区画する。角地に立ち、刻み煙草製造等で栄えた往時をしのばせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011413"},{"id":"00011412","register_sub_id":"101","register_pk":"209249","name":"内田家住宅主屋","kana":"うちだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町サラダ1731-1","lat":34.028257,"lng":133.811664,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0141","desc":"池田の町並みのやや東寄りに西面して建つ。南寄りに土間を通して北半を床上部四室とし、ミセ、座敷を連ねる。土間奥には台所等を突出させる。正面は重厚な袖うだつや出格子窓を構えるほか、室内も良材を用いて意匠を凝らす。地域の特色をよく備える町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011412"},{"id":"00008585","register_sub_id":"101","register_pk":"134981","name":"奥村家住宅蔵","kana":"おくむらけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県板野郡藍住町徳命字前須西166-1-1","lat":34.11580983,"lng":134.48275687,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0088","desc":"主屋の西北に位置する。切石積基礎上に建つ土蔵造二階建。桁行七・六メートル梁間四・九メートルで、南面に石段を付ける。切妻造本瓦葺。内部は壁板張とし、小屋は和小屋。瓦頭に蜂須賀家定紋があり、徳島城の建物を購入した藍商の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008585"},{"id":"00008584","register_sub_id":"101","register_pk":"134980","name":"奥村家住宅主屋","kana":"おくむらけしゅおくじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県板野郡藍住町徳命字前須西166-1-1","lat":34.11571214,"lng":134.48285456,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積128㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0087","desc":"敷地北寄りに南面して建つ。入母屋造茅葺で周囲に桟瓦葺庇をまわす。間口一五メートル奥行七・八メートルで、西寄りに土間を設ける。床上は南北二列からなり、前列東端の八畳にはトコを設け、土間側の六畳正面は窓とする。四方蓋造の穏やかな外観が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008584"},{"id":"00008785","register_sub_id":"101","register_pk":"149506","name":"尾崎家住宅石倉","kana":"おざきけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県吉野川市美郷字中谷189","lat":34.02024634,"lng":134.30574513,"geo_status":"db","era":"明治34年","year":1901,"year_source":"converted","year_min":1901,"year_max":1901,"year_label":null,"structure":"石造2階建、瓦葺、建築面積31㎡","structure_material":"石造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"36 － 0100","desc":"四国山地の山間に位置する。桁行7.1ｍ梁間6.5ｍの石造2階建、切妻造桟瓦葺。近くを流れる東谷川の青石を積み上げ、東面に出入口を穿つ。厚さは足下で1.4ｍ。隅は算木積。内部は三和土で、荒壁塗。山の木立を背景として安らぎある景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008785"},{"id":"00006739","register_sub_id":"101","register_pk":"107722","name":"鎌村家住宅北井戸","kana":"かまむらけじゅうたくきたいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.06351349,"lng":134.07703941,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、面積1.0㎡、洗い場付","structure_material":"石造","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0066","desc":"主屋の北に位置する石組井戸である。地元産の青石４枚を相欠に組む、高さ０．５ｍ、方０．８ｍの角形井筒。井戸は直径０．７ｍで、深さ３．３ｍを測り、内壁を石積とする。井戸まわりに南北２．１ｍ、東西２．８ｍの石敷の洗い場を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006739"},{"id":"00006729","register_sub_id":"101","register_pk":"107712","name":"鎌村家住宅蔵","kana":"かまむらけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.06344986,"lng":134.0767905,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積189㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0062","desc":"主屋西に位置する土蔵造２階建の南北棟。桁行８間梁間３間規模で、屋根は切妻造本瓦葺。内部は南寄り３間を間仕切り倉庫、北を米蔵とし、それぞれ東面に戸口を設け、本瓦葺小庇をつける。小屋組は登梁である。外壁は中塗仕上げで、特徴的な外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006729"},{"id":"00006728","register_sub_id":"101","register_pk":"107711","name":"鎌村家住宅主屋","kana":"かまむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.063454,"lng":134.077042,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積281㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0061","desc":"敷地中央に南面して建つ、木造つし２階建の切妻造平入。表側の下屋とも本瓦葺で、西面と北面に鉄板葺庇が巡る。当初は桁行７間規模の四間取平面と推定され、西に座敷８畳と次の間を増築した。外壁は妻壁を含め漆喰塗大壁で、重厚な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006728"},{"id":"00006733","register_sub_id":"101","register_pk":"107716","name":"鎌村家住宅中庭土塀","kana":"かまむらけじゅうたくなかにわどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.06330604,"lng":134.07690554,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長16m","structure_material":"土塀","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0068","desc":"主屋の東、風呂の北方に位置する石組井戸。石材は地元産の青石である。板石４枚を相欠に組み、高さ０．５ｍ、１．０ｍ四方の角形井筒。井戸は直径０．８ｍで、深さ７ｍ。井戸まわりに石を敷き、北には方１．５ｍの洗い場があり、縁石を立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006733"},{"id":"00006730","register_sub_id":"101","register_pk":"107713","name":"鎌村家住宅納屋","kana":"かまむらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.06334755,"lng":134.07724253,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0063","desc":"主屋東に位置する木造２階建の南北棟。桁行８間梁間２間半、西面に１間半幅の下屋がつく。屋根は本瓦葺で、南入母屋造、北切妻造とする。内部は南端２間分を居室、北端を馬舎と牛舎とした。東の水田側に設けた切石積の石垣の上に建ち、特色ある屋敷構えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006730"},{"id":"00006734","register_sub_id":"101","register_pk":"107717","name":"鎌村家住宅西土塀","kana":"かまむらけじゅうたくにしどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.06333861,"lng":134.0768016,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長14m","structure_material":"土塀","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0069","desc":"便所の西方にあり、宅地の西端を限る土塀である。蔵の南妻面から南へ１４ｍ延びる。南端は取り壊された土蔵に達していた。基底幅０．５ｍ、総高１．５ｍで、頂部を桟瓦葺とする。北端も、もとは蔵の前身建物に取りついていたと推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006734"},{"id":"00006738","register_sub_id":"101","register_pk":"107721","name":"鎌村家住宅東井戸","kana":"かまむらけじゅうたくひがしいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.06345866,"lng":134.07720287,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、面積0.64㎡、洗い場付","structure_material":"石造","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0067","desc":"主屋の東、風呂の北方に位置する石組井戸。石材は地元産の青石である。板石４枚を相欠に組み、高さ０．５ｍ、１．０ｍ四方の角形井筒。井戸は直径０．８ｍで、深さ７ｍ。井戸まわりに石を敷き、北には方１．５ｍの洗い場があり、縁石を立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006738"},{"id":"00006731","register_sub_id":"101","register_pk":"107714","name":"鎌村家住宅風呂","kana":"かまむらけじゅうたくふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.06339362,"lng":134.07723142,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積5.1㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0064","desc":"主屋の東方、納屋の北に隣接する木造平屋建。桁行１４尺梁間４尺の東西棟で、切妻造本瓦葺とする。切石の基礎上に建ち、外壁は真壁造の中塗仕上げである。西から６尺が風呂で、北面に窓、西面に開戸を設ける。東から４尺は大便所で、北面に開戸が付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006731"},{"id":"00006732","register_sub_id":"101","register_pk":"107715","name":"鎌村家住宅便所","kana":"かまむらけじゅうたくべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字坊僧231","lat":34.06331989,"lng":134.07685316,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"36 － 0065","desc":"主屋の西、土蔵の南に位置する木造平屋建。桁行１１尺梁間６尺規模の東西棟で、切妻造本瓦葺とする。東から４尺ずつに仕切り、大便所２室とし、西端は小便所と推定される。戸口は北面にあり、南面の外壁下部に開口をとって汲取口とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006732"},{"id":"00011416","register_sub_id":"101","register_pk":"209253","name":"亀長家住宅蔵","kana":"かめながけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町マチ2266-2他","lat":34.029048,"lng":133.812018,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積62㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0145","desc":"主屋の背面西寄りに南北棟で建つ土蔵。桁行一三メートル、梁間五メートルで屋根は桟瓦葺。砂岩の切石を基礎とし、東面に扉口を開いて一・二階とも一室とする。二階には天井を張り、小屋組を見せない。煙草製造や物資の集積地として栄えた地域の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011416"},{"id":"00011415","register_sub_id":"101","register_pk":"209252","name":"亀長家住宅主屋","kana":"かめながけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町マチ2266-2他","lat":34.028869,"lng":133.812075,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0144","desc":"長方形敷地に南面して建つ。木造二階建、切妻造の平入で、正面西寄りに土間を設けてマエノマ（ミセ）とし、居室四室の背後には中庭を設け、その奥にヌレエンを介して浴室等を配する。袖うだつを構える外観や、豪壮な根太天井など意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011415"},{"id":"00001307","register_sub_id":"101","register_pk":"102297","name":"旧大磯家住宅","kana":"きゅうおおいそけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡松茂町広島字北川向四ノ越29-1","lat":34.14176428,"lng":134.58175044,"geo_status":"db","era":"天保年間","year":1836,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保年間","structure":"木造平屋建，瓦葺，建築面積186㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0029","desc":"阿波之里に移築保存され工芸館として利用されている。大磯家は藍製造とその商取引で栄えた家として知られる。住宅は切妻造，瓦葺で漆喰で塗り込めた主体部の四方に瓦葺の庇を廻した形になる。太い柱梁を用いた架構に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001307"},{"id":"00001306","register_sub_id":"101","register_pk":"102296","name":"旧樫野家住宅","kana":"きゅうかしのけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県板野郡松茂町広島字北川向四ノ越29-1","lat":34.14184834,"lng":134.58122062,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造２階建，瓦葺，建築面積381㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0028","desc":"徳島空港に近い阿波之里に移築保存され迎賓館として利用されている。樫野家は石灰販売で栄えた家で，住宅は入母屋造，２階建の大規模な建物。良質な材料をふんだんに用いた建物で，１階に広間を持つことや２階のせいが高い外観等に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001306"},{"id":"00014682","register_sub_id":"101","register_pk":"515224","name":"旧熊谷家住宅主屋","kana":"きゅうくまがいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻86","lat":34.02908056,"lng":133.88008333,"geo_status":"db","era":"明治3年／明治13年増築、平成15年改修","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造3階建、瓦葺、建築面積73㎡","structure_material":"木造3階建","registered":"2023.08.07(令和5.08.07)","register_no":"36 - 0224","desc":"辻町中心部の伊予街道に面する乾物商の町家。切妻造平入桟瓦葺２階建の後寄りに、妻を正面に向けた入母屋造３階を増築した。内部は１階は通り土間と前土間及び居室の一列型。３階座敷は欄間、座敷飾、襖絵等上質な造作。歴史的町並みの往時の賑わいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014682"},{"id":"00014683","register_sub_id":"101","register_pk":"515225","name":"旧熊谷家住宅倉庫","kana":"きゅうくまがいけじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和中","pref":"徳島県","address":"徳島県三好市井川町辻86","lat":34.02912222,"lng":133.87983611,"geo_status":"db","era":"昭和38年／昭和48年改修","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"36 - 0225","desc":"辻町の乾物商の主屋背面にある乾物用倉庫。切妻造平入桟瓦葺の二階建で、１階を倉庫、２階を和室として階段に主屋から廊下で接続する。地下物置へ中庭に階段口を設ける。正面は腕木庇を付し、真壁造漆喰仕上で引違戸を建てる。主屋と一体で歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014683"},{"id":"00012824","register_sub_id":"101","register_pk":"367727","name":"栗尾家住宅主屋","kana":"くりおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県三好市東祖谷釣井105","lat":34.02586361,"lng":133.80725278,"geo_status":"db","era":"江戸末期／昭和28年頃増築・同63年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺(金属板仮葺)、建築面積139㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"36 － 193","desc":"祖谷川上流の釣井集落の農家主屋。南正面の寄棟造茅葺で、東から土間付の茶ノ間、中ノ間、座敷を並べ、中ノ間奧を寝間とする。正面と西側面に縁を廻し、さらに正面に濡縁を通して中央に便所を設ける。祖谷地方の伝統民家の形式をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012824"},{"id":"00010069","register_sub_id":"101","register_pk":"196216","name":"佐藤家住宅隠居屋","kana":"さとうけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県徳島市入田町笠木200-6","lat":34.04105104,"lng":134.44490289,"geo_status":"db","era":"昭和3／平成25改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積56㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"36 － 0115","desc":"敷地西面北寄りに位置する鉄筋コンクリート造の隠居屋。北半を蔵、南半を畳敷の座敷とし、浴室を突出させる。外壁は腰廻りや入口上部の庇、塔屋を含め、モルタル洗出しで石造風に仕上げる。県内初期の鉄筋コンクリート造技術と伝統的左官技法が融合した建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010069"},{"id":"00011418","register_sub_id":"101","register_pk":"209255","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町マチ2343","lat":34.029617,"lng":133.81211,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0147","desc":"木造二階建、本瓦葺平入の町家。正面右手にミセを配し、通り土間は半間幅で左手に通す。ミセの背後に一〇畳間を介して中庭を取り、二階は四室とする。正面に袖うだつを備え、一階袖壁も漆喰塗とし、その脇を海鼠壁とするなど、地域の中で特色ある外観を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011418"},{"id":"00010070","register_sub_id":"101","register_pk":"196217","name":"佐藤家住宅門柱","kana":"さとうけじゅうたくもんちゅう","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県徳島市入田町笠木200-1","lat":34.0409006,"lng":134.44499054,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"コンクリート造門柱2基、間口2.8m","structure_material":"コンクリート造門柱2基","registered":"2014.04.25(平成26.04.25)","register_no":"36 － 0116","desc":"敷地南面の中央に位置する正門。高さ三メートルのコンクリート造の門柱で、表面は洗出し仕上げとし、柱頂部は皿斗に似た形の柱頭飾りを付す。門柱上部には鉄製のアーチを架け、中央に飾り付きの照明を付す。隠居屋とともに昭和初期の佇まいを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010070"},{"id":"00011409","register_sub_id":"101","register_pk":"209246","name":"地蔵寺寳珠院表門及び塀","kana":"じぞうじほうじゅいんおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県小松島市松島町字松島104","lat":34.00834286,"lng":134.58250483,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"門 木造、瓦葺、間口2.3m 塀 木造、銅板葺、総延長34m","structure_material":"門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"36－0138","desc":"敷地の南面を画す。表門は間口二・三メートルで、切妻造本瓦葺。塀は竪羽目板で、笠木を銅板で覆い、門脇は基礎石を含め曲線状に納める。表門欄間に雲形の透かし彫りを施し、二枚建の連子格子戸は二枚とも東側の戸袋に引き込むなど、細かな細工が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011409"},{"id":"00011405","register_sub_id":"101","register_pk":"209242","name":"地蔵寺寳珠院釜屋","kana":"じぞうじほうじゅいんかまや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県小松島市松島町字松島104","lat":34.00848,"lng":134.582493,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積73㎡、塀付","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0134","desc":"主屋の東にほぼ接する形で建つ。木造二階建、切妻造本瓦葺で、下屋は主屋と同じく桟瓦葺とする。一階南半は石敷土間で竈を設け、北半は物置等とする。二階は中央の吹き抜けを挟んで南に女衆部屋、北に男衆部屋を取る。主屋の土間部の機能が分離したもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011405"},{"id":"00011407","register_sub_id":"101","register_pk":"209244","name":"地蔵寺寳珠院蔵","kana":"じぞうじほうじゅいんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県小松島市松島町字松島104","lat":34.008614,"lng":134.582326,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡、塀付","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0136","desc":"主屋背面側に建ち、敷地の北西隅を画す。土蔵造二階建、切妻造で本瓦葺とする。桁行一一メートル、梁間四・八メートルの規模で、南面には縁を設け、離れや主屋とつなぐ。内部は一階を二室、二階を一室とし、家財道具等を収める。敷地景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011407"},{"id":"00011404","register_sub_id":"101","register_pk":"209241","name":"地蔵寺寳珠院主屋","kana":"じぞうじほうじゅいんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県小松島市松島町字松島104","lat":34.008477,"lng":134.582367,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡、塀付","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0133","desc":"徳島の外港として栄えた小松島市街地に建つ、切妻造本瓦葺の二階建で、南面し、四方に桟瓦葺下屋を設ける。東寄りに玄関土間を配し、庭に面する南西隅表座敷には二方に内縁をとる。二階も全体を居室とし、南東隅を一二畳座敷とする。近代和風住宅の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011404"},{"id":"00011410","register_sub_id":"101","register_pk":"209247","name":"地蔵寺寳珠院中門及び塀","kana":"じぞうじほうじゅいんちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県小松島市松島町字松島104","lat":34.00837864,"lng":134.58240239,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"門 木造、瓦葺、間口1.2m 塀 木造、瓦葺、総延長5.9m","structure_material":"門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"36－0139","desc":"主屋玄関脇から真南に伸びて表側の塀とを結び、内庭を区画する。総延長七・一メートルの桟瓦葺で、基礎石上に竪板を羽重ねに張り、上部は漆喰塗として竹連子の欄間を設ける。中央部には間口一間、両開き板戸の塀中門を開く。敷地の景観を整える塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011410"},{"id":"00011411","register_sub_id":"101","register_pk":"209248","name":"地蔵寺寳珠院西塀","kana":"じぞうじほうじゅいんにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県小松島市松島町字松島104","lat":34.0084617,"lng":134.58225415,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土塀、瓦葺、延長25m","structure_material":"土塀","registered":"2016.11.29(平成28.11.29)","register_no":"36－0140","desc":"敷地の西側を画す土塀。北端は蔵の西南隅に、南端は正面側の塀に接する。延長二五メートルで、高さは三・六メートル。表側の塀の高さまでの腰部を竪板張、上部を漆喰塗とし、桟瓦を葺く。長い白漆喰塗の壁で、地域の景観を形づくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011411"},{"id":"00011406","register_sub_id":"101","register_pk":"209243","name":"地蔵寺寳珠院離れ","kana":"じぞうじほうじゅいんはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県小松島市松島町字松島104","lat":34.008556,"lng":134.582412,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積24㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0135","desc":"主屋の背面側東寄りに建ち、主屋の内縁に接続する。木造二階建、寄棟造桟瓦葺で、一階には居室と便所、湯殿を配し、二階は八畳半の一室として屋久杉を用いた棹縁天井、紙貼の壁などで意匠を凝らしている。上質な内容を持つ離れで、住宅機能拡張の過程を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011406"},{"id":"00011408","register_sub_id":"101","register_pk":"209245","name":"地蔵寺寳珠院便所","kana":"じぞうじほうじゅいんべんじょ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県小松島市松島町字松島104","lat":34.008492,"lng":134.582272,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積8.6㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0137","desc":"主屋表座敷内縁の北端に接続する来客用便所。桟瓦葺で、西側を切妻、主屋側を寄棟でまとめる。入口脇には飾棚を設け、天井の一部を網代張とする。外部も南面小庇を皮付丸太垂木の銅板葺とし、東・北の腰部を丸竹張とするなど、小ぶりながら意匠を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011408"},{"id":"00012049","register_sub_id":"101","register_pk":"210990","name":"島尾家住宅離れ","kana":"しまおけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻85-2","lat":34.029085,"lng":133.879816,"geo_status":"db","era":"明治10年頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造4階建、瓦葺、建築面積127㎡","structure_material":"木造4階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-169","desc":"店舗兼主屋の背面側に位置する。木造四階建で、花頭窓を備える楼閣風の特色ある外観を見せ、三階には一〇畳座敷と七畳半の次の間の南と西に縁を廻らす。四階は畳敷六畳の周囲に板間を配し、遊戯室として使われたと伝える。町並景観の核となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012049"},{"id":"00011414","register_sub_id":"101","register_pk":"209251","name":"住吉家住宅主屋","kana":"すみよしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町マチ2223","lat":34.029301,"lng":133.809178,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積216㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0143","desc":"間口一六メートル強の大規模商家。正面向かって左に広い土間を取り、右を床上部とし、背面に内庭を構えてその奥を渡り廊下を介した便所等とする。重厚な袖うだつを構え、一階の座敷一〇畳は棹縁天井を曲線状に張るなど内部意匠にも贅を尽くした建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011414"},{"id":"00012051","register_sub_id":"101","register_pk":"210992","name":"曽我部家住宅蔵","kana":"そがべけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻2他","lat":34.027521,"lng":133.879321,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-0171","desc":"敷地の背面東寄りに建つ。土蔵造二階建、桟瓦葺で、桁行七・九メートル、梁間四・九メートルの西面に下屋を設ける。外壁は軒まで塗籠め、扉口は北側街路に向かって開き、一、二階とも一室とする。染物作業のための蔵と伝え、地域の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012051"},{"id":"00012050","register_sub_id":"101","register_pk":"210991","name":"曽我部家住宅主屋及び納屋","kana":"そがべけじゅうたくしゅおくおよびなや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻2他","lat":34.027444,"lng":133.879249,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積139㎡","structure_material":"木造2階一部平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"36-0170","desc":"井川町辻中心地の南寄り、井内谷川の北岸に建つ。曽我部家は藍染等も手がけた商家で、木造二階建、切妻造桟瓦葺で、桁行一一・六メートル、梁間七・四メートルの南面西寄りに玄関を、北面西寄りに風呂場を突出させ、東には納屋を設ける。辻の隆盛を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012050"},{"id":"00012052","register_sub_id":"101","register_pk":"210993","name":"曽我部家住宅長屋門","kana":"そがべけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻2他","lat":34.027417,"lng":133.87937,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"36-0172","desc":"敷地東面を画す木造平屋建、切妻造桟瓦葺で、門口の南に倉庫、物置、外便所を配す。街路側の壁は基礎石上に腰簓子下見板張、上部漆喰塗とする。外側の街路は井内谷川に降りる石段へと続くもので、藍染など河川と関わりの深い屋敷のあり方を象徴する門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012052"},{"id":"00001304","register_sub_id":"101","register_pk":"102294","name":"高橋家住宅表門","kana":"たかはしけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市南矢三町2-5-22","lat":34.082539,"lng":134.525253,"geo_status":"db","era":"明治20代","year":1887,"year_source":"converted","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造一間薬医門，瓦葺","structure_material":"木造一間薬医門","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0026","desc":"屋敷地の正面中央にある瓦葺の薬医門。屋敷地正面の境界よりもわずかに引き込んで建てるなど，小規模ながら丁寧なつくりになる武家風の意匠をもった門で，もと藩士であったという高橋家の出自をしのばせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001304"},{"id":"00001300","register_sub_id":"101","register_pk":"102290","name":"高橋家住宅主屋","kana":"たかはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県徳島市南矢三町2-5-22","lat":34.08270766,"lng":134.52528472,"geo_status":"db","era":"寛政11","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積138㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0022","desc":"高橋家はもと徳島藩士で，明治維新後に現在の住宅の土地・家屋を購入し藍の製造を行ったと伝える。主屋は棟札により寛政１１年の建立が明らかで，茅葺の主体部四方に瓦葺の庇を設ける「四方蓋」と呼ばれるこの地方特有の形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001300"},{"id":"00001305","register_sub_id":"101","register_pk":"102295","name":"高橋家住宅練塀","kana":"たかはしけじゅうたくねりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市南矢三町2-5-22","lat":34.08253315,"lng":134.52514185,"geo_status":"db","era":"明治20代","year":1887,"year_source":"converted","year_min":1887,"year_max":1887,"year_label":null,"structure":"練塀，瓦葺，延長39.1m","structure_material":"練塀","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0027","desc":"表門の左右に連なる塀で，西側は折れ曲がって西納屋南面へと繋がり，東側は東納屋の西面に接続している。地元産の緑泥片岩等の小規模な石を多数積み上げて上部を漆喰塗りとした特徴ある構法が用いられており，美しい外観意匠がつくりだされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001305"},{"id":"00012993","register_sub_id":"101","register_pk":"368071","name":"多田家住宅洋館（旧若衆宿）","kana":"ただけじゅうたくようかん（きゅうわかしゅうやど）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県海部郡海陽町大里字浜崎50-1他","lat":33.60285556,"lng":134.35786389,"geo_status":"db","era":"大正4年／昭和55年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"36 － 198","desc":"旧海南町中心部の海運業者宅にある旧若衆宿。寄棟造桟瓦葺の木造二階建、正面中央の入母屋の突出部を二階部屋付の玄関ポーチとし、階境に庇を廻す。外壁は下見板張で、縦長窓を装飾枠やペディメントで飾るなど丁寧につくる。集落景観に存在感を示す洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012993"},{"id":"00012055","register_sub_id":"101","register_pk":null,"name":"立川家住宅内蔵","kana":"たつかわけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻159-1","lat":34.029639,"lng":133.880584,"geo_status":"db","era":"明治36年頃","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-175","desc":"土蔵造二階建、切妻造本瓦葺、桁行四・九メートル、梁間三・九メートルの南北棟で、中庭を囲む主屋側は腰海鼠壁、上部漆喰塗で、軒まで塗籠とする。主屋背面に延びる廊下を蔵前として南面に扉口を開き、内部は一、二階とも一室とする。敷地景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012055"},{"id":"00012056","register_sub_id":"101","register_pk":"210997","name":"立川家住宅蔵","kana":"たつかわけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻159-1","lat":34.029655,"lng":133.880249,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鋼板葺、建築面積107㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-176","desc":"敷地西端に建つ土蔵造二階建、切妻造銅板葺で、北面、東面に深く庇を張り出す。桁行、梁間とも七・九メートルの正方形平面で、庇上に各二所設けられた二階窓には格子を入れ、上部に水切瓦を付ける。小屋は登梁を用いる。煙草産業で栄えた地域の歴史を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012056"},{"id":"00012053","register_sub_id":"101","register_pk":"210994","name":"立川家住宅主屋","kana":"たつかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻159-1","lat":34.029618,"lng":133.880695,"geo_status":"db","era":"明治36年頃","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-173","desc":"辻の町並内の街道筋から吉野川方へ下る道に東面して建つ。立川家は近世から刻み煙草の製造販売を行った家で、つし二階を持つ切妻造桟瓦葺。正面庇上には袖うだつを備える。各種銘木を配した一階オモテの座敷周りなど、上質な内部造作も特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012053"},{"id":"00012054","register_sub_id":"101","register_pk":"210995","name":"立川家住宅離れ","kana":"たつかわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市井川町辻159-1","lat":34.029592,"lng":133.880498,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-174","desc":"敷地の中程に建つ。桁行一一・〇メートル、梁間六・〇メートル、切妻造桟瓦葺の二階建で、化粧持送りで支える出桁や、戸袋を千鳥模様とするなど特徴ある意匠を備える。煙草の専売後他所で成功した当主が戻るために建てたもので、地域の歴史を象徴している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012054"},{"id":"00011834","register_sub_id":"101","register_pk":"210850","name":"谷家住宅表門及び塀","kana":"たにけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県海部郡美波町日和佐浦184","lat":33.732704,"lng":134.537532,"geo_status":"db","era":"明治3年頃","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"表門 木造、瓦葺、間口2.1m 塀 土塀、瓦葺、総延長46m","structure_material":"表門 木造","registered":"2017.06.28(平成29.06.28)","register_no":"36-0166","desc":"ミセの西に建ち、敷地南面を中央を画す表門とこれより西へ矩折れに続く塀。表門は間口四・六メートルの棟門で腕木には繰形彫刻が施される。塀は小石を積み上げた土塀で、街路側には、一部に海鼠壁が残り、街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011834"},{"id":"00011832","register_sub_id":"101","register_pk":"210848","name":"谷家住宅産屋","kana":"たにけじゅうたくさんや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県海部郡美波町日和佐浦184","lat":33.732645,"lng":134.537227,"geo_status":"db","era":"明治3年頃","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"36-0164","desc":"主屋北西に縁を介して接続する。内部は一室でオサンベヤと称され、南北面に縁を設ける。室内は、西半を網代張の落天井とし西南隅に釣床を設ける。また、北縁東面の格子窓は天袋・地袋を付け瀟洒に飾る。生活の一端を伝え、貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011832"},{"id":"00011831","register_sub_id":"101","register_pk":"210847","name":"谷家住宅主屋","kana":"たにけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県海部郡美波町日和佐浦184","lat":33.732593,"lng":134.537364,"geo_status":"db","era":"明治3年頃","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"36-0163","desc":"日和佐港沿い街区に建つ。入母屋造で南面玄関は大斗肘木と虹梁の妻飾をもつ切妻屋根を載せる。西半は座敷、仏間を田の字型に、東半は応待の間や台所など諸室を配する。二階を三区分し、各々階段を設け独立性を保つ。海運業で栄えた往時を偲ばせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011831"},{"id":"00011833","register_sub_id":"101","register_pk":"210849","name":"谷家住宅ミセ","kana":"たにけじゅうたくみせ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県海部郡美波町日和佐浦184","lat":33.732508,"lng":134.537437,"geo_status":"db","era":"明治3年頃","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"36-0165","desc":"主屋前方に通り土間を介して接続する。切妻造桟瓦葺で、南面道路に向かって下屋庇を付け、出格子を設ける。内部は東半を土間、西半をミセとし、天井はミセ部を根太天井、土間部は舟底天井とし、趣向を凝らす。漁師町にふさわしい景観を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011833"},{"id":"00012991","register_sub_id":"101","register_pk":"368115","name":"篪庵","kana":"ちいおり","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県三好市東祖谷釣井209","lat":33.86406111,"lng":133.86233889,"geo_status":"db","era":"江戸中期／平成22年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"36 － 196","desc":"祖谷川上流の釣井集落のもと農家主屋。東正面の寄棟造茅葺で、外壁をヒシャギ竹張で養生する。北から土間付のチャノマ、ナカノマ、オモテの3室を並べ、ナカノマ裏を寝間、オモテ表を縁側とする。見晴らしのよい山腹に建ち、山村集落の景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012991"},{"id":"00012823","register_sub_id":"101","register_pk":"367726","name":"中山家住宅主屋","kana":"なかやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市東祖谷久保311","lat":34.02586361,"lng":133.80725278,"geo_status":"db","era":"大正前期／平成29年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、茅葺(金属板仮葺)、建築面積167㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"36 － 192","desc":"祖谷川上流の久保集落の農家主屋。南正面の寄棟造茅葺、南西二面を出桁造とし、濡縁と吹放し下屋を廻す。東から土間付の茶ノ間、中ノ間、座敷を並べ、中ノ間奧を寝間とする。見晴らしのよい南斜面中腹に建ち、山村集落の景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012823"},{"id":"00001647","register_sub_id":"101","register_pk":"102637","name":"原田家住宅主屋","kana":"はらだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県徳島市かちどき橋3-43","lat":34.06070058,"lng":134.55441683,"geo_status":"db","era":"江戸後期／明治15移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積204㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"36 － 0030","desc":"明治初期に名東県の大属を努めた原田一平が元徳島藩主蜂須賀茂韶から譲り受けたと伝え，約１０年を費やして明治１５年に現在地に移築した。前後３列に居室を並べて，一部二階建とし，屋根は切妻造の本屋の四周に庇を廻す。大規模武家住宅の姿を良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001647"},{"id":"00014294","register_sub_id":"101","register_pk":"509684","name":"平岡家住宅主屋","kana":"ひらおかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県海部郡海陽町大里字飯持18","lat":33.60636389,"lng":134.35603333,"geo_status":"db","era":"明治5年／昭和前期","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積120㎡","structure_material":"木造平屋一部2階建","registered":"2022.06.29(令和4.06.29)","register_no":"36 - 0217","desc":"鞆城下の集落に所在する農家建築。二階建、切妻造平入、四方に下屋を回し、外壁下見板張。内部は東側を元は広い土間、西側床上を食違い四間取とし、庭向きに濡縁を回す床構え付表座敷を設け、中の間に幅一間の玄関を配す。当地方近世民家の定型を継承する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014294"},{"id":"00014295","register_sub_id":"101","register_pk":"509685","name":"平岡家住宅台所","kana":"ひらおかけじゅうたくだいどころ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県海部郡海陽町大里字飯持18","lat":33.60645,"lng":134.35604444,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"36 - 0218","desc":"鞆城下の集落の農家主屋背面に建つ台所棟。平屋建、平入で東面を入母屋造、西面を切妻造、外壁は下見板張で軒際を漆喰仕上とする。内部は南半を板敷床上として竿縁天井とし、北半は元土間で井戸ポンプを設置するいわゆる釜屋で、農家の屋敷構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014295"},{"id":"00014296","register_sub_id":"101","register_pk":"509686","name":"平岡家住宅納屋","kana":"ひらおかけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"徳島県","address":"徳島県海部郡海陽町大里字飯持18","lat":33.60639722,"lng":134.35619444,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"36 - 0219","desc":"主屋の東に西面して建つ納屋兼居室棟。二階建北面角屋付で、切妻造妻入桟瓦葺、外壁下見板張。一階は納屋と倉庫で芋蔵を設け、深い下屋庇を作業場とし、北面角屋は倉庫及び牛小屋。二階は床付き座敷の続き間居室を設ける。農家の生業や習俗の様子を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014296"},{"id":"00014297","register_sub_id":"101","register_pk":"509687","name":"平岡家住宅西塀","kana":"ひらおかけじゅうたくにしへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県海部郡海陽町大里字飯持18","lat":33.60648333,"lng":134.35586667,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、延長21m","structure_material":"石造","registered":"2022.06.29(令和4.06.29)","register_no":"36 - 0220","desc":"鞆城下集落に所在する農家の石垣で、武家町に面する。通り沿いから主屋に向けてＬ字形に延び、主屋表座敷が面する庭園を囲む。延長21・2メートル、砂岩の割石を六段布積にし、出角は算木積として反りを付ける。城下の歴史的景観に寄与する重厚な石垣。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014297"},{"id":"00014298","register_sub_id":"101","register_pk":"509688","name":"平岡家住宅南塀","kana":"ひらおかけじゅうたくみなみへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県海部郡海陽町大里字飯持18","lat":33.60633333,"lng":134.35590556,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、瓦葺、延長13m","structure_material":"土塀","registered":"2022.06.29(令和4.06.29)","register_no":"36 - 0221","desc":"鞆城下集落に所在する農家の土塀。主屋正面で、敷地内通路と主屋を区画する。下部に江戸切り仕上の砂岩切石を三段布積にし、その上に漆喰仕上の土塀を建てる。屋根は桟瓦葺で、棟は熨斗瓦四段積に雁振瓦を載せる。屋敷地の重厚な表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014298"},{"id":"00011420","register_sub_id":"101","register_pk":"209257","name":"藤田家住宅裏納屋兼離れ","kana":"ふじたけじゅうたくうらなやけんはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県板野郡北島町新喜来字南古田57","lat":34.128983,"lng":134.545849,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積122㎡","structure_material":"木造2階一部平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0149","desc":"主屋背面、敷地の北西隅に建つ。西半の納屋は外壁下見板張の切妻造二階建。東半の離れは入母屋の平屋で、主屋と渡廊下を介して接続し、東と南に内縁を廻らして六畳間と八畳座敷を置く。内縁天井は磨き丸太の扇垂木を疎らに配すなど内部意匠にも意を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011420"},{"id":"00011422","register_sub_id":"101","register_pk":"209259","name":"藤田家住宅蔵","kana":"ふじたけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県板野郡北島町新喜来字南古田57","lat":34.128876,"lng":134.545869,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0151","desc":"主屋西方に建つ。柱を密に立てる土蔵造二階建、切妻造本瓦葺で、内部は一・二階とも一室とし、南妻右寄りに扉口を開く。基礎石を高く積んで床面を高め、腰部は下見板張り、上部は軒まで漆喰で塗籠める。古くから洪水に悩まされた河口域の蔵の特色を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011422"},{"id":"00011419","register_sub_id":"101","register_pk":"209256","name":"藤田家住宅主屋","kana":"ふじたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県板野郡北島町新喜来字南古田57","lat":34.128883,"lng":134.546007,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0148","desc":"吉野川河口域の三角州平野に建つ農家。敷地中央に南面して建つ。切妻造本瓦葺で、四方に下屋をかける。土間を三室に区画し、二階南端に季節ごとに建具を入れ替えるための七畳大納戸を設ける。近代における農家の好例で、地域の農村景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011419"},{"id":"00011423","register_sub_id":"101","register_pk":"209260","name":"藤田家住宅長屋門及び塀","kana":"ふじたけじゅうたくながやもんおよびへい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県板野郡北島町新喜来字南古田57","lat":34.12872718,"lng":134.54592897,"geo_status":"db","era":"明治38／明治41・昭和前期増築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"長屋門 木造平屋建、瓦葺、建築面積39㎡ 塀 鉄筋コンクリート造、延長12m","structure_material":"長屋門 木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0152","desc":"敷地西面南方を画す。南から番屋、牛小屋、門、便所を配し、北にドイツ壁風の鉄筋コンクリート塀を蔵まで延ばす。屋根はいずれも本瓦葺とし、門は一段高く切り上げる。番屋と牛小屋は下見板張り、便所は腰モルタル上部漆喰塗とし、変化のある表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011423"},{"id":"00011421","register_sub_id":"101","register_pk":"209258","name":"藤田家住宅納屋","kana":"ふじたけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県板野郡北島町新喜来字南古田57","lat":34.128874,"lng":134.546143,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0150","desc":"敷地東端の中ほどに建つ納屋。後補の下屋を介して主屋の南東隅に接する。木造二階建、切妻造本瓦葺で、桁行七・八メートル、梁間四・九メートルの規模を有する。小屋は登梁と水平梁を混用する。農作業の用具等を納め、屋敷の機能上欠くことのできない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011421"},{"id":"00002023","register_sub_id":"101","register_pk":"103013","name":"三井翠松園（旧三井高達別荘）別館","kana":"みついすいしょうえん（きゅうみついたかみちべっそう）べっかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県鳴門市瀬戸町大島田字中山1-1","lat":34.24281667,"lng":134.61216111,"geo_status":"db","era":"昭和5／昭和30頃・平成18移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"14 － 0048","desc":"本館の西方に建つ。東京代々木に所在した深川の材木商の邸宅を移築したものと伝える。主室部は木造平屋建，寄棟造で，１２畳半２室を主室とし，その周囲三方に１間幅の畳廊下を巡らす。材木商の邸宅らしく吟味された素材と欄間等の凝った意匠に特色がある。平成１８年３月に、神奈川県箱根町から徳島県鳴門市に移築された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002023"},{"id":"00012058","register_sub_id":"101","register_pk":"210999","name":"三舩家住宅蔵","kana":"みふねけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県三好市井川町辻183-1","lat":34.030109,"lng":133.88124,"geo_status":"db","era":"天保10年（1839）","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-178","desc":"主屋の南方に建つ。土蔵造二階建、平入、切妻造桟瓦葺で桁行九・九メートル、梁間五・〇メートルの規模である。野面積の基礎を高く取り、壁は軒まで塗籠る。一階は二室に区切り、それぞれの扉口外に石積階段を設ける。二階は一室とする。町並景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012058"},{"id":"00012057","register_sub_id":"101","register_pk":"210998","name":"三舩家住宅主屋","kana":"みふねけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県三好市井川町辻183-1","lat":34.030195,"lng":133.881232,"geo_status":"db","era":"嘉永7年（1854）","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造2階建、瓦葺、建築面積124㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-177","desc":"井川町辻の東寄りに位置する。三舩家は地域でも古くより刻み煙草の製造を行っていた家で、主屋は木造二階建、切妻造桟瓦葺で、正面右に玄関口を開き、当初は背面側まで土間を通していた。煙草産業で栄えた地域の近世以来の景観を今に伝える住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012057"},{"id":"00011417","register_sub_id":"101","register_pk":"209254","name":"宮本家住宅主屋","kana":"みやもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町マチ2339-1","lat":34.029628,"lng":133.812232,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積149㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"36－0146","desc":"南面して建つ。左に通り土間を取り、床上部正面土間側をミセとし、居室四室の背後に中庭を配する構成はこの地域の標準的な姿。二階も四室とする。袖うだつを備え伝統的な意匠でまとめるが、正面出格子下や中庭側の二階手摺子などに洋風意匠も取り入れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011417"},{"id":"00012059","register_sub_id":"101","register_pk":"211000","name":"向井家住宅主屋","kana":"むかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県三好市井川町向坂32-1","lat":34.025096,"lng":133.879091,"geo_status":"db","era":"安政2年（1855）","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造2階建、瓦葺、建築面積199㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-179","desc":"辻の中心地から井川谷川沿に山へと上がる道筋に位置する、敷地形状から船形屋敷と称されていた住宅。つし二階を持つ切妻造本瓦葺で、整形六間取平面の正面左に式台玄関を構え、背面には下屋を張り出す。近世以来の地域の歴史的景観を今に伝える住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012059"},{"id":"00016733","register_sub_id":"101","register_pk":"579217","name":"森家住宅主屋","kana":"もりけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市入田町笠木83","lat":34.04033,"lng":134.44289,"geo_status":"db","era":"明治前期／昭和3年・同56年・平成20年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積177㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"36 - 0230","desc":"鮎喰川右岸の集落に位置する旧家の主屋。敷地中央に南面して建つ寄棟造平入茅葺（鉄板仮葺）で四周に本瓦葺下屋を廻らし、北西に台所棟を突出。西は旧土間、東は５室を並べ、南東は床構え付の座敷とする。南面中央の式台玄関など、旧家の格式を留める主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016733"},{"id":"00016734","register_sub_id":"101","register_pk":"579218","name":"森家住宅釜屋","kana":"もりけじゅうたくかまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県徳島市入田町笠木83","lat":34.040431,"lng":134.442848,"geo_status":"db","era":"昭和3年頃／昭和56年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"36 - 0231","desc":"主屋の北西に位置する台所棟。平屋建で北は入母屋造、南は切妻造とし、全体本瓦葺とする。外壁は漆喰塗で、簓子下見板を高く張る。内部は一室で南側を踏込の土間、北側は板床を張る。小規模ながら本瓦葺とした重厚な外観で、旧家の屋敷構えを構成する釜屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016734"},{"id":"00016738","register_sub_id":"101","register_pk":"579222","name":"森家住宅北塀","kana":"もりけじゅうたくきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市入田町笠木83","lat":34.040422,"lng":134.442951,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、総延長43m、木戸門付","structure_material":"石造","registered":"2026.07.09(令和8.07.09)","register_no":"36 - 0235","desc":"敷地の北から東を画す長大な石塀。折曲り延長四三メートル、基部の幅約一メートルの分厚い塀で、不整形な緑色片岩を乱積とし、頂部は平板で整える。東北角は隅切に造り、中央やや東寄りに片開板戸の戸口を開く。荒々しい存在感が特色ある地域の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016738"},{"id":"00016735","register_sub_id":"101","register_pk":"579219","name":"森家住宅米蔵","kana":"もりけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市入田町笠木83","lat":34.040438,"lng":134.442775,"geo_status":"db","era":"明治38年","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"36 - 0232","desc":"敷地の北西隅に東面して建つ米蔵。二階建切妻造平入本瓦葺で、外壁は漆喰塗で軒まで塗込め、東面の戸口に腕木庇を付す。各階は板敷の一室で、中央の通柱で地棟を受け、小屋は登梁を水平の繋梁で繋ぐ。妻の拝みに波と亀の鏝絵を飾るなど、丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016735"},{"id":"00016737","register_sub_id":"101","register_pk":"579221","name":"森家住宅中門及び袖塀","kana":"もりけじゅうたくちゅうもんおよびそでべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市入田町笠木83","lat":34.040255,"lng":134.442871,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"中門 木造、瓦葺、間口1.2m 袖塀 木造、瓦葺、総延長8.7m","structure_material":"中門 木造","registered":"2026.07.09(令和8.07.09)","register_no":"36 - 0234","desc":"主屋南西の庭を画する中門及び袖塀。中門は西面して建つ切妻造本瓦葺の小振な総欅の腕木門で、門口に両開の板扉を建てる。袖塀は主屋と長屋門の間に折曲がり延びる両下造桟瓦葺で、内外を竪板張、下見板張とし、上部に欄間を設ける。敷地導入部の景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016737"},{"id":"00016736","register_sub_id":"101","register_pk":"579220","name":"森家住宅長屋門","kana":"もりけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県徳島市入田町笠木83","lat":34.040228,"lng":134.44295,"geo_status":"db","era":"明治中期／昭和56年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"36 - 0233","desc":"敷地の東面南寄りに位置する長屋門。入母屋造本瓦葺の南北棟で、外壁は下見板張で上部を黒漆喰塗仕上とする。通りに面して出格子窓を構える。南端は広い門口とし、北は二室の和室を配する。基礎や門口廻りには長尺の緑色片岩を用い、重厚なつくりとした表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016736"},{"id":"00016740","register_sub_id":"101","register_pk":"579224","name":"森家住宅東塀","kana":"もりけじゅうたくひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市入田町笠木83","lat":34.040258,"lng":134.443034,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造、延長7.1m","structure_material":"鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"36 - 0237","desc":"長屋門と北塀の間に設けた塀。延長約七メートル、高さ約一・八メートル、鉄筋コンクリート造で、緑色片岩の石積上に建つ。外側は鎧状に２段の見切を付し、上・下方にスリット状の開口を設けるなど全体に凝ったつくり。風格ある屋敷の表構えを形成する東塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016740"},{"id":"00016739","register_sub_id":"101","register_pk":"579223","name":"森家住宅南塀","kana":"もりけじゅうたくみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市入田町笠木83","lat":34.040208,"lng":134.442809,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、延長32m","structure_material":"石造","registered":"2026.07.09(令和8.07.09)","register_no":"36 - 0236","desc":"敷地の南辺を画す長大な石塀。折曲り延長約三二メートルで、形や大きさが比較的に揃った緑色片岩を乱積とし、頂部は平板で整える。東隅部は大きめの切石を用いて積み上げる。北塀よりも洗練された精緻なつくりとし、地域の特徴的な景観を形成する長大な石塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016739"},{"id":"00010519","register_sub_id":"101","register_pk":"199460","name":"森本家住宅表門","kana":"もりもとけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県勝浦郡勝浦町大字坂本字生実32","lat":33.93209167,"lng":134.44658691,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.0m","structure_material":"木造","registered":"2015.03.26(平成27.03.26)","register_no":"36 － 0124","desc":"離れの南の通路に建つ、一間薬医門、切妻造本瓦葺。棟は青海波として鬼瓦に鳥衾を載せ、破風拝に鰭付懸魚を吊る。柱間は板戸両開とし、北側柱は離れ南側の板塀に接し、南は本柱と控柱の間に下見板を張り、石垣に接続する。谷あいの屋敷地入口を飾る門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010519"},{"id":"00010514","register_sub_id":"101","register_pk":"199455","name":"森本家住宅主屋","kana":"もりもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県勝浦郡勝浦町大字坂本字生実32","lat":33.932258,"lng":134.446399,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積176㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"36 － 0119","desc":"黄檗川支流の谷あいの敷地に南面する。桁行八間梁間五間半、寄棟造茅葺（鉄板仮葺）で、下屋は本瓦葺とし、土間の竈上部に切妻の煙出を付す。平面は西を土間とし、床上部は前後二列に部屋を並べ南東を主座敷として縁を廻らす。山間地の近世民家の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010514"},{"id":"00010518","register_sub_id":"101","register_pk":"199459","name":"森本家住宅新蔵","kana":"もりもとけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県勝浦郡勝浦町大字坂本字生実32","lat":33.932305,"lng":134.446337,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"36 － 0123","desc":"主屋北側東寄り、古蔵に並んで建つ。土蔵造二階建、切妻造本瓦葺で南面戸口に下屋を付す。外壁漆喰塗で腰を簓子下見板張とし、内部は竪板張とする。鉢巻の妻面拝みに鰭付懸魚を模した鏝細工を飾り、窓額縁にも鏝絵を付すなど、意匠的工夫が施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010518"},{"id":"00010516","register_sub_id":"101","register_pk":"199457","name":"森本家住宅納屋","kana":"もりもとけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県勝浦郡勝浦町大字坂本字生実32","lat":33.932067,"lng":134.446382,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"36 － 0121","desc":"主屋の南西に東面して建つ。建ちの低い二階建で、北面切妻造南面入母屋造、本瓦葺とし、東と南に下屋、北東に風呂を附属する。一階内部はほぼ同規模の二室とし、二階は北を大部屋とした二室である。主屋正面を囲む納屋であり、屋敷地の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010516"},{"id":"00010515","register_sub_id":"101","register_pk":"199456","name":"森本家住宅離れ","kana":"もりもとけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県勝浦郡勝浦町大字坂本字生実32","lat":33.932258,"lng":134.446571,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"36 － 0120","desc":"主屋の南西に建つ離れ。入母屋造及び切妻造桟瓦葺で東面以外の三方に縁を廻らし本瓦葺の下屋とする。八畳と六畳を並べ、ケヤキやツガ、屋久杉などの良材を使うほか、サルスベリの落掛、技巧的な床脇、精緻な透彫欄間など、見応えある上質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010515"},{"id":"00010517","register_sub_id":"101","register_pk":"199458","name":"森本家住宅古蔵","kana":"もりもとけじゅうたくふるぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県勝浦郡勝浦町大字坂本字生実32","lat":33.932241,"lng":134.446275,"geo_status":"db","era":"文化6(1809)","year":1809,"year_source":"db","year_min":1809,"year_max":1809,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"36 － 0122","desc":"主屋北側西寄りに南面して建つ。土蔵造二階建、切妻造本瓦葺で、南面戸口に下屋を付す。外壁は漆喰塗で鉢巻を廻らし、腰を簓子下見板張とする。二階南面と西面に窓を配し、片開の鉄扉を付ける。内部は板床で壁は竪板張とする。近世の庄屋の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010517"},{"id":"00012063","register_sub_id":"101","register_pk":"211004","name":"山下家住宅表門","kana":"やましたけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻78-1","lat":34.028441,"lng":133.880109,"geo_status":"db","era":"明治32年頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造、瓦葺、間口1.5m、袖塀付","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"36-183","desc":"街路に面した主屋の西側に接して建つ。間口一・五メートルの棟門で、左右に塀を延ばす。いずれも本瓦葺とし、塀の腰部は幅の狭い簓子下見板張で、上部を土壁とする。戸口上には松の彫刻透かし欄間を嵌める。総欅造の上質な門で街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012063"},{"id":"00012062","register_sub_id":"101","register_pk":"211003","name":"山下家住宅米蔵","kana":"やましたけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻76-2他","lat":34.02837,"lng":133.87981,"geo_status":"db","era":"明治16年","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-182","desc":"主屋背面側、敷地の西端に建つ。土蔵造二階建、切妻造本瓦葺一部桟瓦葺。内部は三室に区切り、東面に扉口二所を開くが、背面側中央の入口はかつての水路から荷揚げに用いられたと伝え、煙草等の生産地、集散地として栄えた辻の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012062"},{"id":"00012060","register_sub_id":"101","register_pk":"211001","name":"山下家住宅主屋","kana":"やましたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻76-2他","lat":34.028369,"lng":133.880046,"geo_status":"db","era":"明治32年","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積216㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-180","desc":"山下家は井川町辻の中心を抜ける街道の南北に敷地を構える。主屋は南北棟の木造二階建、切妻造で、正面中央に玄関を取り、その南に土間を通し、さらに南にはミセと居室を配している。起りを持つ本瓦葺の大屋根が特徴的で、町並の景観を特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012060"},{"id":"00012065","register_sub_id":"101","register_pk":"211006","name":"山下家住宅別邸","kana":"やましたけじゅうたくべってい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県三好市井川町辻332-1","lat":34.028159,"lng":133.880139,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-185","desc":"主屋から街路を挟んで北側に建つ。二階建、切妻造本瓦葺で、正面に下屋をもうけ、屋根上両端に袖うだつを設ける。二階の建ちが高く、平入の大屋根に起りを持たせて街路側に見せる点も特徴的で、辻の町並中心部の歴史的景観の核となる町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012065"},{"id":"00012061","register_sub_id":"101","register_pk":"211002","name":"山下家住宅味噌蔵","kana":"やましたけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻76-2他","lat":34.028424,"lng":133.879959,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-181","desc":"主屋の背面側北寄りに東西棟で建つ。土蔵造二階建、切妻造本瓦葺、平入で、桁行九・九メートル、梁間四・九メートル。一、二階とも二室に区切り、一階は西半を土間、東半を板張とする。雑貨商で扱う商品を収めていたと伝え、辻の隆盛を今に伝える蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012061"},{"id":"00003315","register_sub_id":"101","register_pk":"104305","name":"旅館たおか蔵屋","kana":"りょかんたおかくらや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬市脇町大字脇町字北町165-1","lat":34.0684339,"lng":134.14826662,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"36 － 0046","desc":"２階建の土蔵造で，南北棟の切妻造・本瓦葺，平入になり，西面中央を庇付の出入口とし，小窓には銅板扉を設ける。外壁は漆喰塗とするが，街路に面した腰を簓子下見板張とする。屋敷の東南隅にあり，西に接している表門とともに，街路景観の要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003315"},{"id":"00003313","register_sub_id":"101","register_pk":"104303","name":"旅館たおか主屋","kana":"りょかんたおかしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬市脇町大字脇町字北町165-1","lat":34.06853296,"lng":134.1481799,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積262㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"36 － 0044","desc":"もと呉服商の別邸で，大正末期より旅館となった。主屋は東向きの主体部と，この西北に建つ北西棟からなり，ともに木造２階建である。主体部は西側に角屋を突出してＴ字型棟の本瓦葺屋根で，正面は南端に式台玄関を持つが，切妻造・平入の町家風外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003313"},{"id":"00004829","register_sub_id":"101","register_pk":"105819","name":"愛染家住宅離れ","kana":"あいぜんけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市東ハゼ町897","lat":34.32295863,"lng":134.04035685,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"37 － 0274","desc":"主屋中庭の中央に建つ４畳半一間の離れ。桁行２間梁行１間半，北妻を切妻造，南妻を寄棟造とした南北棟，桟瓦葺の木造平屋建で，東南西の３面に擬宝珠高欄を廻し，南面中央に太鼓橋を架けて主屋と連絡する。木割の細い，繊細な意匠の数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004829"},{"id":"00004030","register_sub_id":"101","register_pk":"105020","name":"阿波屋岡田家住宅主屋","kana":"あわやおかだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県小豆郡小豆島町坂手字中甲592","lat":34.45799799,"lng":134.32319908,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積146㎡、石垣付","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0195","desc":"坂手港を望む高台に位置する。部屋を１列に並べ矩折としたＬ字形平面に特徴があり，西端に床・棚・書院付きの座敷，入隅に玄関を設け，南に土間を突き出す。外観は片入母屋造，本瓦葺のつし２階建で，つし２階の隅部に鍔形状の漆喰彫刻を施すのも特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004030"},{"id":"00004031","register_sub_id":"101","register_pk":"105021","name":"阿波屋岡田家住宅門長屋及び納屋","kana":"あわやおかだけじゅうたくもんながやおよびなや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県小豆郡小豆島町坂手字中甲592","lat":34.45791006,"lng":134.32336314,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造及び土蔵造2階建、瓦葺、建築面積73㎡","structure_material":"木造及び土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0196","desc":"小豆島第三番霊場観音寺参道から西に入った脇道の突き当たりに位置する。門長屋は桁行４間規模の切妻造，本瓦葺で，門口両脇に落棟の物置を従える。門長屋の東に接する納屋は，桁行４間半規模，東西棟，切妻造，本瓦葺で，北に角屋を出してコ字形平面とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004031"},{"id":"00000275","register_sub_id":"101","register_pk":"101265","name":"磯野家住宅","kana":"いそのけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市生野町2146-1","lat":34.22203337,"lng":133.78405295,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建，瓦葺，建築面積255㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"37 － 0010","desc":"和風住宅の正面玄関脇に小規模な２階建ての洋館を取り付けた形の住宅。洋館部はモルタル仕上げで，頂部に装飾を持つ柱形や１・２階の間にある帯状の装飾に特徴がある。大正から昭和初期に多くみられる和風住宅に洋館を付した住宅建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000275"},{"id":"00012829","register_sub_id":"101","register_pk":"367732","name":"岩瀬家住宅板塀","kana":"いわせけじゅうたくいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県坂出市新浜町3328","lat":34.31240389,"lng":133.84642694,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、総延長41m","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 436","desc":"主屋玄関南脇から東に延びる塀と同北脇から矩折れに北に延びる塀からなる。高さ2・6メートル、土台に立てた柱を棟木と貫でつなぎ、出桁を通して瓦屋根をかけ、柱間は縦板張目板打で上部を吹寄せ襷格子とする。繊細な意匠で主屋正面の構えを優雅に演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012829"},{"id":"00012831","register_sub_id":"101","register_pk":"367734","name":"岩瀬家住宅植込枠石組","kana":"いわせけじゅうたくうえこみわくいしぐみ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県坂出市新浜町3331-1","lat":34.31240389,"lng":133.84642694,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、延長16m","structure_material":"石造","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 438","desc":"表門前方から北に延びて街路に接続する通路を構成する施設。長さ16メートル、通路両側に幅0・7メートルで花崗岩石積を立上げ、その上端部に花崗岩切石を並べて植込みとする。大規模かつ精巧なつくりの石組で豪商宅に相応しい堂々たる表構えを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012831"},{"id":"00012828","register_sub_id":"101","register_pk":"367731","name":"岩瀬家住宅表門","kana":"いわせけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県坂出市新浜町3328-2","lat":34.31240389,"lng":133.84642694,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.1m、南脇潜戸付","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 435","desc":"敷地東北隅、敷地境から少し内側に東面して建つ。間口2・1メートル、起り屋根の切妻造本瓦葺、薬医門形式で、五平の本柱の両脇に壁を設けて南側に潜戸を設ける。冠木と控柱の虹梁形頭貫の上に4本の梁を渡して軒桁を受ける。豪商宅の表構えを重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012828"},{"id":"00012825","register_sub_id":"101","register_pk":"367728","name":"岩瀬家住宅主屋","kana":"いわせけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県坂出市新浜町3328","lat":34.31240389,"lng":133.84642694,"geo_status":"db","era":"明治23年頃／昭和7年頃増築・改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建一部2階建、瓦葺、建築面積283㎡","structure_material":"木造平屋建一部2階建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 432","desc":"市街地西部の角山北麓にある製塩業者の住宅。主屋は敷地中央に東面して建つ。南北棟の入母屋造桟瓦葺の平屋建で、南端を東西棟の二階建とする。正面中央に玄関、北端に続き間の座敷、二階に和洋居室4室を設ける。豪商の近代の暮らしを伝える大規模和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012825"},{"id":"00012826","register_sub_id":"101","register_pk":"367729","name":"岩瀬家住宅新座敷","kana":"いわせけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県坂出市新浜町3328","lat":34.31240389,"lng":133.84642694,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 433","desc":"主屋背面の北端に接続して建つ。東西棟の寄棟造桟瓦葺の二階建で、一階に続き間の座敷、二階西端に座敷を設ける。座敷飾は磨き丸太の床柱や黒檀の床框、付書院の遠見霞欄間など上下階を同じ近代的意匠でまとめる。主屋とともに屋敷構えの中核を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012826"},{"id":"00012827","register_sub_id":"101","register_pk":"367730","name":"岩瀬家住宅道具蔵","kana":"いわせけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県坂出市新浜町3328","lat":34.31240389,"lng":133.84642694,"geo_status":"db","era":"明治44年頃","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 434","desc":"主屋背面の中庭に東面して建つ。土蔵造二階建、切妻造本瓦葺で正面に下屋を通し、中央に戸口を設ける。外壁は漆喰塗で腰と四隅を海鼠壁とする。内部は上下階とも板敷で壁縦板張、小屋組はトラスである。大規模かつ丁寧なつくりで中庭の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012827"},{"id":"00012830","register_sub_id":"101","register_pk":"367733","name":"岩瀬家住宅土塀","kana":"いわせけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県坂出市新浜町3328-2","lat":34.31240389,"lng":133.84642694,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土塀、瓦葺、総延長47m","structure_material":"土塀","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 437","desc":"表門の両側に延び、敷地の東面北半から北面東半にかけてを区切る塀。高さ2・4メートル、石垣または石積上に漆喰塗の土塀を築いて瓦屋根をかける構成で、壁体の出隅妻は中央部に入八双風の図柄をあしらう。表門とともに豪商宅の表構えを重厚に整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012830"},{"id":"00014524","register_sub_id":"101","register_pk":"513938","name":"漆原家住宅主屋","kana":"うるしはらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市三谷町字西三谷東1377-1","lat":34.28078333,"lng":134.0642,"geo_status":"db","era":"江戸後期／明治35年頃・昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（銅板仮葺）一部瓦葺、建築面積321㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0477","desc":"讃岐平野辺縁の田園地帯に位置する郷士宅。主屋は規模の大きい四方蓋造で南面し、東半土間の大戸口に加え、式台を構える。床上は二列六室を基本としながら計一一室に区切る変則的な平面とし、南にトモマチベヤを角屋で出す。木割も太く格式を見せ豪壮である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014524"},{"id":"00014529","register_sub_id":"101","register_pk":"513943","name":"漆原家住宅木納屋","kana":"うるしはらけじゅうたくきなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市三谷町字西三谷東1377-1","lat":34.28048889,"lng":134.06468611,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0482","desc":"屋敷地南東角にあり、水肥納屋と並んで建つ納屋。切妻造本瓦葺で、桁行一六・四メートルを測る。通り側は土蔵造で一切の開口を設けず、敷地内側は開放とする。内部は土間で東西に仕切る。かつては木納屋として用いたと伝わる。重厚な敷地外郭を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014529"},{"id":"00014530","register_sub_id":"101","register_pk":"513944","name":"漆原家住宅中門及び袖塀","kana":"うるしはらけじゅうたくちゅうもんおよびそでへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市三谷町字西三谷東1377-1","lat":34.28065,"lng":134.06412778,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口1.3m、総延長25m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0483","desc":"旧家の屋敷入口側と座敷庭を区画する門と塀。塀は主屋式台から長屋門を繋ぐ南北塀で、主屋寄りに薬医門形式の中門を、南端で東に折れて引戸の腕木門を開く。東面は大壁造の漆喰仕上、西面は真壁造黒漆喰仕上に腰板張とする。旧家に相応しい屋敷景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014530"},{"id":"00014526","register_sub_id":"101","register_pk":"513940","name":"漆原家住宅土蔵","kana":"うるしはらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市三谷町字西三谷東1377-1","lat":34.28102222,"lng":134.06421389,"geo_status":"db","era":"明治前期／昭和後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0479","desc":"敷地の北寄りに東西棟で建つ土蔵。切妻造本瓦葺の二階建、内部を各階二室に区切り、二階の二室は金網張窓で繋ぎ、床板は目透し張で通気を確保。正面は渡り廊下で東西を仕切り、東半は主屋土間側に開く米蔵、西半は座敷側に開く道具蔵で、敷地利用に対応する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014526"},{"id":"00014531","register_sub_id":"101","register_pk":"513945","name":"漆原家住宅土塀","kana":"うるしはらけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市三谷町字西三谷東1377-1他","lat":34.28102778,"lng":134.063875,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土塀、瓦葺、延長262m","structure_material":"土塀","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0484","desc":"屋敷地東・北・西の三面と、南面西端から長屋門まで囲繞する長大な土塀。延長二六二メートルを測り、瓦葺、外側漆喰・内側中塗仕上。石積に建ち、南面切込み矧ぎ、堀を設けた三面打込み矧ぎとする。北東部平面は敷地に合わせ弧を描き、高い築造技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014531"},{"id":"00014527","register_sub_id":"101","register_pk":"513941","name":"漆原家住宅長屋門","kana":"うるしはらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市三谷町字西三谷東1377-1","lat":34.28050556,"lng":134.06432222,"geo_status":"db","era":"江戸後期／明治前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0480","desc":"屋敷地南辺中央に開く。桁行二六・三メートルと長大な長屋門。屋根は入母屋造本瓦葺、門口の東側に二室、西側に一室を配し、東端の木納屋側は大工部屋と伝わる。通りに面して格子の高窓を開け、郷士宅の正面を飾るに相応しい堂々とした長屋門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014527"},{"id":"00014528","register_sub_id":"101","register_pk":"513942","name":"漆原家住宅水肥納屋","kana":"うるしはらけじゅうたくみずごえなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市三谷町字西三谷東1377-1","lat":34.28048611,"lng":134.06452222,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積34㎡、脇門付","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0481","desc":"屋敷南辺にある水肥の製造と貯蔵に用いた建物。長屋門の東に続く本瓦葺平屋建、東脇に脇門を開く。通り側は大壁で開口を設けず、敷地内側は開放的に造る。室内は床を張らず大型の甕を三基設け、東側に物置を配す。当地域の農業の様相を伝える貴重な水肥納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014528"},{"id":"00014525","register_sub_id":"101","register_pk":"513939","name":"漆原家住宅湯殿","kana":"うるしはらけじゅうたくゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県高松市三谷町字西三谷東1377-1","lat":34.28074722,"lng":134.06403889,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0478","desc":"主屋座敷の西に濡れ縁で接続する賓客用湯殿と便所。切妻造で元本瓦葺、真壁造で軸組に丸太を多用。南半は湯殿で棚付洗い場や鉄砲風呂を備える。東に開放の廊下を通し、北半は便所で青磁の便器を用いる。四分円や真円の下地窓を開け、瀟洒な意匠の接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014525"},{"id":"00000274","register_sub_id":"101","register_pk":"101264","name":"大川家住宅","kana":"おおかわけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市上吉田町三丁目１０５２－１、１０５３、１０５４","lat":34.22867457,"lng":133.78191212,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建，瓦葺，建築面積134㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"37 － 0009","desc":"主屋の西側に接続して増築された洋館。おもに応接用に使われている。装飾のある玄関ポーチ，急勾配の屋根，縦長の窓，モルタル仕上げの外壁等を用いた外観の意匠は，重厚な和風の主屋とは対照的で，ひときわ目立つ洋館として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000274"},{"id":"00004042","register_sub_id":"101","register_pk":"105032","name":"大三宅（三宅家住宅）主屋","kana":"おおみやけ（みやけけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県香川郡直島町本村字高田浦855-1","lat":34.46073187,"lng":133.99671417,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積201㎡、庭門及び塀付","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0207","desc":"本村港を臨む敷地に建つ。桁行９間梁行６間規模，切妻造，本瓦葺で，八間取とし，東南隅に１間半の土間を設ける。座敷部と居室部とで床段差をとり，式台以西の座敷部前面には錣屋根を架け，居室部はつし２階に見せる。島内で最も格式の高い家として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004042"},{"id":"00004043","register_sub_id":"101","register_pk":"105033","name":"大三宅（三宅家住宅）長屋門及び供部屋","kana":"おおみやけ（みやけけじゅうたく）ながやもんおよびともべや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県香川郡直島町本村字高田浦855-1","lat":34.46062972,"lng":133.9968291,"geo_status":"db","era":"文政4","year":1821,"year_source":"db","year_min":1821,"year_max":1821,"year_label":null,"structure":"木造2階建、瓦葺、建築面積86㎡、塀付","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0208","desc":"主屋の南方に位置し東西棟で建つ。桁行６間梁間２間，入母屋造，本瓦葺の２階建長屋門で，主屋式台玄関に対応して門口を開き，北面東方は土庇を差し掛けて蔵前をとるとともに井戸を覆う。東面には桁行３間の供部屋が取り付き，庄屋に相応しい門構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004043"},{"id":"00016441","register_sub_id":"101","register_pk":"536508","name":"大山家住宅主屋","kana":"おおやまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市水主4536","lat":34.23543333,"lng":134.31905556,"geo_status":"db","era":"江戸末期／明治4年頃増築、令和2年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺(鉄板仮葺)一部瓦葺、建築面積227㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"37 - 0494","desc":"虎丸山北麓に位置する大庄屋の主屋。敷地中央に南面する寄棟造平入茅葺(鉄板仮葺)で四周に本瓦葺下屋を廻らす。内部東に土間、西に２列６室を並べる。西寄りに式台を構え、上手を続き間座敷とし、北西室に床を構える。広い式台など格式を備えた大規模な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016441"},{"id":"00008199","register_sub_id":"101","register_pk":"132640","name":"苧坂家住宅長屋門","kana":"おさかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県綾歌郡綾川町西分字東浦谷1443","lat":34.19983997,"lng":133.95279587,"geo_status":"db","era":"明治29年","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0367","desc":"丘陵地に占める敷地の南端に南面して建つ。桁行１７ｍ梁間５．０ｍの木造平屋建、入母屋造本瓦葺。中央西寄りに門口を開き、その西に使用人部屋、東に馬小屋と物置を配す。腰に下見板を張り、軒までを土壁で塗り込める。山間の集落に、威風ある姿を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008199"},{"id":"00003602","register_sub_id":"101","register_pk":"104592","name":"かめびし蔵","kana":"かめびしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22875604,"lng":134.40328524,"geo_status":"db","era":"明治後期／昭和初期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造及び木造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造及び木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0159","desc":"敷地の西北角に位置し，主屋の北方に東西棟で建つ。桁行８ｍ梁間５ｍ規模，切妻造，本瓦葺の２階建土蔵で，基礎を花崗石積，腰を海鼠壁とし，東妻面側に桁行４ｍ規模の蔵前をとる。西妻面の上部には創業者である岡田家の「三ツ柏」の家紋を付けて由緒を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003602"},{"id":"00003601","register_sub_id":"101","register_pk":"104591","name":"かめびし資材置場","kana":"かめびししざいおきば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22846373,"lng":134.40349038,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0158","desc":"主屋座敷部の東方に中庭を介して建つ。もとの離れ座敷で，桁行１２ｍ梁間７ｍ規模，東西棟，入母屋造，本瓦葺の平屋建とし，南と西に下屋庇を廻す。内部は大きく改造されてはいるが，本瓦葺の屋根が商家住居部の主要素としての面影を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003601"},{"id":"00003000","register_sub_id":"101","register_pk":"103990","name":"川鶴酒造川鶴資料館（旧米蔵）","kana":"かわつるしゅぞうかわつるしりょうかん（きゅうこめぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町1029-1","lat":34.12688731,"lng":133.70830038,"geo_status":"db","era":"大正期／昭和30頃移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0125","desc":"鶴鳴舘の西方に位置し，南側敷地南辺のほぼ中央に東西棟で建つ。桁行９ｍ，梁間４ｍ規模，切妻造，本瓦葺，平入の２階建土蔵で，外装の腰部を海鼠壁，上部を白漆喰壁とする。もと北側敷地内住居部の米蔵を曳家したもので，現在は酒造用具等の展示場に活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003000"},{"id":"00004650","register_sub_id":"101","register_pk":"105640","name":"キッコ石石井家住宅主屋","kana":"きっこいしいしいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲262","lat":34.47645679,"lng":134.32186972,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積158㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0242","desc":"山裾傾斜地に石垣擁壁で造成した屋敷地の北方に東西棟で建つ。入母屋造，桟瓦葺の四周に下屋を廻した木造平屋建で，桁行１６ｍ梁行１０ｍの平面規模とし，東方を土間，西方を床上部とする。主屋根軒下の小壁や外壁は黒漆喰塗で重厚な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004650"},{"id":"00004653","register_sub_id":"101","register_pk":"105643","name":"キッコ石石井家住宅土蔵","kana":"きっこいしいしいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲262","lat":34.47638317,"lng":134.32173272,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡、石垣付","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0245","desc":"離れ屋の西方に位置する。桁行２間半梁間２間規模，切妻造，本瓦葺，妻入の２階建土蔵で，外部は土台石上部を海鼠壁，腰を焼杉縦板張，上部の壁や軒鉢巻を白漆喰塗とする。高窓の縁取りなども丁寧なつくり。縄弛みを持つ石垣基壇上に建つことで際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004653"},{"id":"00004651","register_sub_id":"101","register_pk":"105641","name":"キッコ石石井家住宅長屋門","kana":"きっこいしいしいけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲262","lat":34.47637517,"lng":134.321991,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積170㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0243","desc":"主屋の東方に南北棟で建つ。桁行１７ｍ規模，切妻造，桟瓦葺の木造平屋建で，東西両側面に下屋を架けてつし２階風に見せ，東面の門口北方に切妻造の角屋を突出し，南妻面前方には一段低い石垣擁壁上に入母屋造の居室を繋げる。屋敷構えの中核をなす建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004651"},{"id":"00004652","register_sub_id":"101","register_pk":"105642","name":"キッコ石石井家住宅離れ屋","kana":"きっこいしいしいけじゅうたくはなれや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲262","lat":34.47634114,"lng":134.32177707,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積36㎡、庭門付","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0244","desc":"主屋の南方に位置し，主屋の庭より１階分低いところに築いた石垣擁壁上に建つ。南北棟，入母屋造，本瓦葺の木造２階建で，四周に桟瓦葺の下屋を廻す。１階を物置，２階を居室とし，外壁は１階を焼杉縦板張，上部白漆喰塗で，東面に角木瓜形の小窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004652"},{"id":"00015388","register_sub_id":"101","register_pk":"532512","name":"旧石川家住宅主屋","kana":"きゅういしかわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県坂出市元町三丁目1468","lat":34.31796389,"lng":133.85532222,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺一部銅板葺、建築面積173㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"37 - 0492","desc":"坂出駅北側の住宅地に位置する和風住宅の主屋。敷地北寄りに南面して建つ二階建寄棟造平入本瓦葺で北東に平屋棟を附属。北西の庭に面する主座敷は床脇に天袋、地袋など備えた端正なつくり。二階は大壁とした重厚な外観でガラス戸の多用など時代相を示す主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015388"},{"id":"00016743","register_sub_id":"101","register_pk":"579227","name":"旧小西家住宅（西谷）主屋","kana":"きゅうこにしけじゅうたく（にしのたに）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県さぬき市長尾名字西ノ谷1432-1","lat":34.247302,"lng":134.182606,"geo_status":"db","era":"明治34年／昭和中期増築、平成13年頃改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積326㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"37 - 0497","desc":"市街地南東部に位置する旧家の主屋。広大な敷地中央に南面して建つ、つし二階建入母屋造本瓦葺で四周に下屋を廻らす。南面中央に式台玄関を配し、東は御勘定場や台所、西は１５畳と１０畳の座敷を並べる。大床を構えた玄関など、旧家の格式を示す大規模主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016743"},{"id":"00014684","register_sub_id":"101","register_pk":"515226","name":"旧南原家住宅主屋","kana":"きゅうなんばらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市亀水町610-1","lat":34.37178056,"lng":133.94241944,"geo_status":"db","era":"大正元年／令和4年改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積208㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"37 - 0486","desc":"高松市西端の亀水湾で製塩業を営んだ旧家の主屋。起り付の寄棟造平入本瓦葺、つし二階建、出桁軒裏及び二階壁を塗込黒漆喰仕上で外観を引き締める。内部は六間取を基本に床上部分広壮で、仏間を上段の間、床構えは鍵座敷で設ける。上質な近代和風の民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014684"},{"id":"00014687","register_sub_id":"101","register_pk":"515229","name":"旧南原家住宅長屋門","kana":"きゅうなんばらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市亀水町610-1","lat":34.37165833,"lng":133.94260833,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡、袖塀付","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"37 - 0489","desc":"亀水湾で製塩業を営んだ旧家の長屋門。敷地正面で蔵の間に建つ。切妻造平入桟瓦葺、真壁造鼠漆喰仕上腰板張、東半が門、西半を長屋とする。竪格子欄間付中央門扉の両脇に潜り戸、袖塀に通用口と、使い分けを窺わせる。屋敷表構えで集落の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014687"},{"id":"00014686","register_sub_id":"101","register_pk":"515228","name":"旧南原家住宅南東蔵","kana":"きゅうなんばらけじゅうたくなんとうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市亀水町610-1","lat":34.37170278,"lng":133.94266111,"geo_status":"db","era":"明治5年／平成14年改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積54㎡","structure_material":"土蔵造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"37 - 0488","desc":"亀水湾で製塩業を営んだ旧家の付属建物。敷地南東隅で長屋門袖塀東に接続。切妻造平入桟瓦葺の土蔵造平屋建。内部は桁行三室に区切り、北室は板敷倉庫、中室は広い土間で唐臼を備え、南室は土間倉庫とする。下屋を付して作業場や納屋に用いた実用的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014686"},{"id":"00014685","register_sub_id":"101","register_pk":"515227","name":"旧南原家住宅南蔵","kana":"きゅうなんばらけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市亀水町610-1","lat":34.37159722,"lng":133.94249722,"geo_status":"db","era":"明治元年／令和4年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"37 - 0487","desc":"亀水湾で製塩業を営んだ旧家の土蔵。敷地正面に長屋門と並ぶ。切妻造妻入桟瓦葺の二階建で中央に独立棟持柱を立てる。１階は土間で、元は米蔵として使用するため柱間に荷摺木を打つ。窓は二階南面に二箇所で閉鎖的。屋敷表構えとなり集落の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014685"},{"id":"00008380","register_sub_id":"101","register_pk":"134022","name":"旧平賀家住宅主屋","kana":"きゅうひらがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県さぬき市志度字越窓46-1他","lat":34.32409854,"lng":134.16874053,"geo_status":"db","era":"文久2年(1862)／昭和9年・昭和42年・平成12年改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"37 － 0368","desc":"旧志度街道に北面する町家。桁行１２ｍ梁間１０ｍの木造つし２階建、東西棟の切妻造の北正面西寄りに、入母屋造妻入のミセ部分を突出する。正背面に庇を付け、本瓦葺とする。漆喰仕上げで、大壁と真壁を使い分け、軒を塗り込めるなど、力強い外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008380"},{"id":"00015090","register_sub_id":"101","register_pk":"529368","name":"旧渡邊家住宅主屋","kana":"きゅうわたなべけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県木田郡三木町大字下高岡字正一2569","lat":34.26820833,"lng":134.14500278,"geo_status":"db","era":"江戸末期／昭和36年増築、令和5年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（銅板仮葺）及び瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"37 - 0490","desc":"白山駅西方に位置する旧家の主屋。切妻造桟瓦葺南北棟の北に入母屋造茅葺（銅板仮葺）の東西棟を接続し全体Ｔ字形平面とする。南は玄関と茶室、北西に続き座敷、北東に台所を配す。座敷は漆塗床框に菊花紋を付し、付書院の蕨火頭窓など華やかな数寄屋風意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015090"},{"id":"00015091","register_sub_id":"101","register_pk":"529369","name":"旧渡邊家住宅弧月庵及び白雲軒","kana":"きゅうわたなべけじゅうたくこげつあんおよびはくうんけん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県木田郡三木町大字下高岡字正一2569","lat":34.26828611,"lng":134.14505556,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡、渡廊下付","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"37 - 0491","desc":"主屋の北東に位置する茶室。切妻造桟瓦葺東西棟の東に落棟の切妻屋根を延ばし、周囲に銅板葺庇を廻らす。南面に主屋への渡廊下接続。内部は東が二畳半桝床の白雲軒、西が四畳の弧月庵とする。四半敷の土間や波連子窓など内外に数寄屋風意匠を凝らした茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015091"},{"id":"00003141","register_sub_id":"101","register_pk":"104131","name":"金両藤井家住宅主屋","kana":"きんりょうふじいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.47658855,"lng":134.31814563,"geo_status":"db","era":"大正7頃","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積218㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0134","desc":"敷地南半の住宅部の中央に東西棟で建つ。桁行９間梁間５間規模，入母屋造，桟瓦葺で，外観をつし２階風に造る。南面東寄りに入母屋造の玄関を突き出し，西方上手西南隅に１０畳座敷を配し，東方下手に勘定場・土間を設ける。醸造場主住宅の在り様を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003141"},{"id":"00003142","register_sub_id":"101","register_pk":"104132","name":"金両藤井家住宅土蔵","kana":"きんりょうふじいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.47648617,"lng":134.31833455,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0135","desc":"主屋の東南方に南北棟で建つ。台形平面をもつ切妻造，本瓦葺の２階建土蔵で，北妻面に本瓦葺の蔵前庇を付ける。地棟下端の墨書から建設年が判明する。腰板と漆喰塗壁の境に水切瓦を廻した丁寧なつくりの土蔵で，南妻面の窓庇の持送りに鏝絵装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003142"},{"id":"00003144","register_sub_id":"101","register_pk":"104134","name":"金両藤井家住宅塀","kana":"きんりょうふじいけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.47640383,"lng":134.3180489,"geo_status":"db","era":"大正7頃／昭和4増築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土塀及び煉瓦塀、総延長42m","structure_material":"土塀及び煉瓦塀","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0137","desc":"正門西端に発し，矩折れに敷地南辺を西方にはしり，交差点で北に折れて県道土庄坂手線沿いに敷地西辺を区切る。南塀は高さ１．５ｍ，石造基礎，瓦屋根の土塀とし，県道沿いの西塀は煉瓦造で高く造り主屋庭園を囲う。住宅部の屋敷構に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003144"},{"id":"00008069","register_sub_id":"101","register_pk":"128900","name":"日下家住宅主屋","kana":"くさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田字畑方2250","lat":34.22739685,"lng":134.40400293,"geo_status":"db","era":"江戸末期／明治期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積335㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"37-0335","desc":"旧街道の東側に占める敷地のほぼ中央に南北棟で建つ。入母屋造本瓦葺で周囲に下屋庇をまわし、正面南寄りに入母屋造妻入の式台玄関を設ける。内部は北寄りを土間、南を二列六間取の床上とし、オクやゲンカンにはトコを構える。重厚な造りになる上層農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008069"},{"id":"00008070","register_sub_id":"101","register_pk":"128901","name":"日下家住宅長屋門","kana":"くさかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田字畑方2250","lat":34.2273398,"lng":134.40384914,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"37-0336","desc":"旧街道沿いに西面する。桁行２０ｍ梁間３．９ｍの木造平屋建で、中央に間口３．９ｍの門口を開き、両開戸と両脇に潜りを吊る。入母屋造本瓦葺。出桁造の軒まで白漆喰で塗り込め、正面側には腰下見板張とし、出格子などを付ける。風格ある屋敷構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008070"},{"id":"00006456","register_sub_id":"101","register_pk":"107439","name":"倉の館三角邸（旧堺家住宅）主屋","kana":"くらのやかたさんかくてい（きゅうさかいけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町2147-3","lat":34.30988704,"lng":133.82603169,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階一部平屋建、瓦葺、建築面積157㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"37 － 0313","desc":"元肥料商の接客棟。入母屋造２階建の東西棟が敷地南寄りに建ち、東に入母屋造銅板葺の玄関、北に入母屋造平屋建の南北棟の座敷棟が接続する。座敷棟は座敷１２畳と次の間１０畳からなり、瓦葺庇を巡らす。内外とも丁寧な造作で、富商の接客空間を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006456"},{"id":"00006493","register_sub_id":"101","register_pk":"107476","name":"倉の館三角邸（旧堺家住宅）東門","kana":"くらのやかたさんかくてい（きゅうさかいけじゅうたく）ひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町2147-3","lat":34.30991721,"lng":133.82614028,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口2.0m、左右袖塀付","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"37 － 0315","desc":"敷地の東辺南寄り、主屋玄関の正面に開く門。両側の袖塀で塀に接続する。間口６尺規模の腕木門で、内側に控柱を添える。屋根は切妻造桟瓦葺とする。冠木上に透し彫り欄間を入れ、両開板戸の上部も透し彫り板で飾る。丁寧な造作で、屋敷の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006493"},{"id":"00006494","register_sub_id":"101","register_pk":"107477","name":"倉の館三角邸（旧堺家住宅）塀","kana":"くらのやかたさんかくてい（きゅうさかいけじゅうたく）へい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町2147-3","lat":34.30999038,"lng":133.82599853,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、延長53m","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"37 － 0316","desc":"敷地の東辺と北辺を限る塀。高さ１．８ｍ、折曲り延長５３ｍで、桟瓦葺とする。北面西寄りに裏門を開く。基礎は東面が花崗岩、北面がモルタル塗。真壁造土塗で、１間おきに小窓をあける。腰は外面が竪板張、内面が網代張である。邸宅の外観に風格を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006494"},{"id":"00006457","register_sub_id":"101","register_pk":"107440","name":"倉の館三角邸（旧堺家住宅）洋館","kana":"くらのやかたさんかくてい（きゅうさかいけじゅうたく）ようかん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町2147-3","lat":34.309883,"lng":133.82590969,"geo_status":"db","era":"昭和初期／平成8改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積13㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"37 － 0314","desc":"敷地北寄りに位置する。東西２間半、南北１間半の２階建で、急勾配の四注屋根をかけて尖塔を模す。内部は１、２階とも１室。外壁は隅柱を見せた目地切のモルタル塗で、縦長のアーチ窓を並べる。天然スレート葺を平瓦菱葺に改修し、ステンドグラスを新調した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006457"},{"id":"00002454","register_sub_id":"101","register_pk":"103444","name":"郷屋敷（旧井上家住宅）表門","kana":"ごうやしき（きゅういのうえけじゅうたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33018936,"lng":134.13594006,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口1.8m、左右潜戸付","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0070","desc":"屋敷の正面中央，東側の米蔵と西側の蔵の間に建つ。棟通りの中央が広い門口，左右が幅の狭い潜戸とし，両端部は前後に腕木を延ばして控柱をたてる。切妻造，本瓦葺で，全体として端正なつくりであるが，両側の蔵との取り合いなど，細部の処理が巧みである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002454"},{"id":"00002449","register_sub_id":"101","register_pk":"103439","name":"郷屋敷（旧井上家住宅）北蔵西","kana":"ごうやしき（きゅういのうえけじゅうたく）きたぐらにし","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33054036,"lng":134.13572036,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0065","desc":"屋敷地の北面，北蔵東と東壁を接して西側に建つ。規模は北蔵東よりひとまわり小さいが，棟は高く，現在も倉庫として用いている。２階建，切妻造，桟瓦葺で，南面に下屋庇を設け，外壁を白漆喰塗とする。北蔵東と一体となって屋敷地北面の景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002449"},{"id":"00002448","register_sub_id":"101","register_pk":"103438","name":"郷屋敷（旧井上家住宅）北蔵東","kana":"ごうやしき（きゅういのうえけじゅうたく）きたぐらひがし","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33058906,"lng":134.13583438,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0064","desc":"屋敷地北面のほぼ中央に建ち，離座敷と渡廊下で繋がる。２階建，切妻造，桟瓦葺で，外壁を白漆喰塗とし，開口部は背面に高窓２カ所と閉鎖的なつくりで，現在も倉庫として用いられている。屋敷地とその北側に広がる水田とを明確に区画する要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002448"},{"id":"00002452","register_sub_id":"101","register_pk":"103442","name":"郷屋敷（旧井上家住宅）蔵","kana":"ごうやしき（きゅういのうえけじゅうたく）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.330196,"lng":134.135864,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積50㎡","structure_material":"土蔵造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0068","desc":"屋敷正面の中央西寄に建ち，東側には表門を挟んで米蔵がある。入母屋造，本瓦葺の東西に細長い建物で，南面は腰が簓子下見板張で上部を白漆喰塗とするが，北面は柱を見せた真壁造とする。通りに面する窓に格子を入れるなど，長屋門風の外観とするのは珍しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002452"},{"id":"00002451","register_sub_id":"101","register_pk":"103441","name":"郷屋敷（旧井上家住宅）米蔵","kana":"ごうやしき（きゅういのうえけじゅうたく）こめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33049534,"lng":134.13579464,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0067","desc":"屋敷正面の中央東寄に建ち，西側には表門がある。切妻造，本瓦葺で，腰を海鼠壁，上部を白漆喰塗とし，南面の高窓には鉄扉をつける。平面は平行四辺形となっており，これにあわせて柱を菱形につくるなど，全体として手の込んだ造りになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002451"},{"id":"00002444","register_sub_id":"101","register_pk":"103434","name":"郷屋敷（旧井上家住宅）主屋","kana":"ごうやしき（きゅういのうえけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33038126,"lng":134.13591,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積219㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0060","desc":"井上家は江戸中期以来の旧家で，現在は郷屋敷と称する料理店として活用されている。主屋は敷地中央に建ち，整形８間取の平面で，繊細で緻密な数寄屋風の意匠を随所に備える。当地方で一般的な寄棟造の四周に瓦葺庇を付けた外観であるが，規模は雄大である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002444"},{"id":"00002455","register_sub_id":"101","register_pk":"103445","name":"郷屋敷（旧井上家住宅）中門","kana":"ごうやしき（きゅういのうえけじゅうたく）ちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.330311,"lng":134.136078,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口1.8m、左右練塀延長13m付","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0071","desc":"主屋の南側，やや東寄りに建つ。南北棟の切妻造，本瓦葺の小規模な１間１戸薬医門で，組物を持たず，梁を柱で直接受ける。北側と南側に練塀が延びて，主屋の前庭と南東に築かれた南庭を適切に区分しており，簡素ながら，敷地内の空間構成を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002455"},{"id":"00002446","register_sub_id":"101","register_pk":"103436","name":"郷屋敷（旧井上家住宅）取合廊下","kana":"ごうやしき（きゅういのうえけじゅうたく）とりあいろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33027204,"lng":134.13578838,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0062","desc":"南側の主屋と北側の離座敷を連絡しており，離座敷と同時期に建てられた。平屋建，桟瓦葺で，主屋の北面と離座敷の南面が一体となり口ノ字型の平面になる。全体のつくりは簡素であるが，軒先を受ける彫刻持送り板などに，離座敷と共通する造形がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002446"},{"id":"00002456","register_sub_id":"101","register_pk":"103446","name":"郷屋敷（旧井上家住宅）中練塀","kana":"ごうやしき（きゅういのうえけじゅうたく）なかねりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33058133,"lng":134.13592252,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"練塀、瓦葺、延長14m","structure_material":"練塀","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0072","desc":"離座敷の北側にある延長約１４メートルの練塀。東西方向に築かれており，西端が北蔵東の東壁面に取り付いている。高さ１．８メートルで，頂部を瓦で覆う。敷地東北隅に築かれた奥庭にあって，空間構成の演出に効果を発揮している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002456"},{"id":"00002453","register_sub_id":"101","register_pk":"103443","name":"郷屋敷（旧井上家住宅）西蔵","kana":"ごうやしき（きゅういのうえけじゅうたく）にしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.330425,"lng":134.135712,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0069","desc":"屋敷西面のほぼ中央に建ち，もとは材木などを収納していた。南北に細長い平屋建の土蔵で，屋根は切妻造，桟瓦葺とし，外壁は白漆喰塗で仕上げる。簡素な形態であるが，主屋西側を囲うとともに，屋敷西面の景観を構成する上で欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002453"},{"id":"00002458","register_sub_id":"101","register_pk":"103448","name":"郷屋敷（旧井上家住宅）西練塀","kana":"ごうやしき（きゅういのうえけじゅうたく）にしねりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.3302029,"lng":134.13572126,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"練塀、瓦葺、延長18m","structure_material":"練塀","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0074","desc":"屋敷の西辺南側に築かれた塀で，高さ１．８メートル，折れ曲がり総延長約１８メートルの規模を持ち，南端部は蔵に接する。基礎は安山岩系の石による乱石積で，壁面は荒壁仕上，頂部を瓦で覆う。南西部を巧みに囲っており，屋敷構に必要な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002458"},{"id":"00002445","register_sub_id":"101","register_pk":"103435","name":"郷屋敷（旧井上家住宅）離座敷","kana":"ごうやしき（きゅういのうえけじゅうたく）はなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.330524,"lng":134.135895,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積67㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0061","desc":"南を正面とする主屋の後方に並列して建ち，主屋とは廊下で繋がっている。総２階建，寄棟造，桟瓦葺で，１・２階とも２室構成で，東側の室に床の間を設ける。端正な数寄屋風の意匠で，細部まで丁寧に仕上げられ，棚や床脇障子には洗練された造形がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002445"},{"id":"00002450","register_sub_id":"101","register_pk":"103440","name":"郷屋敷（旧井上家住宅）東蔵","kana":"ごうやしき（きゅういのうえけじゅうたく）ひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33023136,"lng":134.13608143,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0066","desc":"屋敷地の東南隅にある南北棟の細長い建物。本瓦葺の屋根は，南妻が入母屋造，北妻が切妻造になる。２階建で，外壁を白漆喰塗とするが，南端部は真壁造で２階に開口部をつくり，座敷としていた。簡素な形態であるが，屋敷角地の景観を構成する欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002450"},{"id":"00002457","register_sub_id":"101","register_pk":"103447","name":"郷屋敷（旧井上家住宅）東練塀","kana":"ごうやしき（きゅういのうえけじゅうたく）ひがしねりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.33050178,"lng":134.13609484,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"練塀、瓦葺、延長72m","structure_material":"練塀","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0073","desc":"高さ１．８メートル，折れ曲がり総延長約７２メートルの規模を持ち，広大な屋敷地の東辺と北辺を囲っている。基礎は地場産の安山岩系の石を用い，精緻な乱石積とし，壁面を白漆喰塗で仕上げる。大規模な屋敷構の構成上，欠かせない要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002457"},{"id":"00002447","register_sub_id":"101","register_pk":"103437","name":"郷屋敷（旧井上家住宅）元湯殿","kana":"ごうやしき（きゅういのうえけじゅうたく）もとゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県高松市牟礼町大町字羽間1987","lat":34.330452,"lng":134.136169,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0063","desc":"小規模な平屋建で，主屋北東隅に位置し，渡廊下で接続している。本瓦葺屋根は東西棟で東妻が寄棟，西妻は主屋の庇に連続する。内部は湯殿と便所からなるが，湯殿は畳敷の客間として用いている。細い部材や杉皮覆の外壁など，繊細な数寄屋風の意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002447"},{"id":"00004434","register_sub_id":"101","register_pk":"105424","name":"坂下家住宅主屋","kana":"さかしたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲833","lat":34.47637748,"lng":134.31933434,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0225","desc":"木造平屋建，平入で，南北棟で切妻造の４周に下屋庇を廻す，いわゆる四方蓋造の民家。屋根は桟瓦葺だが，下屋庇に一部は本瓦を用いる。平側の下屋上部には漆喰塗の小壁を廻し，鉄格子入の窓を設け，小屋裏は物置とする。明治期の技法を採り入れた民家の事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004434"},{"id":"00004435","register_sub_id":"101","register_pk":"105425","name":"坂下家住宅土蔵","kana":"さかしたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲833","lat":34.47639364,"lng":134.31920281,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0226","desc":"敷地奥，主屋西方にある。桁行５ｍの土蔵造２階建，切妻造で，平側に一段低い切妻造の突出部を設ける。小屋組は登梁式，屋根は桟瓦葺，外壁は漆喰塗，腰を縦板で覆う。妻面２階には庇付の小窓を設け，黒漆喰の縁取が際だつ。小規模だが丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004435"},{"id":"00005368","register_sub_id":"101","register_pk":"106356","name":"坂下勤家住宅主屋","kana":"さかしたつとむけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字坂ノ山甲258","lat":34.47614055,"lng":134.32197838,"geo_status":"db","era":"明治41／大正6・昭和30頃増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積132㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0301","desc":"東西に走る山辺の道北側に屋敷地を構え，敷地中央北寄りに南面して建つ。桁行６間半，梁行３間半，切妻造，桟瓦葺の平屋建で，東方を土間，西方床上を四間取平面とする。四周の下屋の南面に本瓦葺，西面に塗込の軒裏を残し，往時の中級農家景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005368"},{"id":"00005369","register_sub_id":"101","register_pk":"106357","name":"坂下勤家住宅土蔵及び石垣","kana":"さかしたつとむけじゅうたくどぞうおよびいしがき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字坂ノ山甲258","lat":34.47608207,"lng":134.32185948,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡、石垣延長20m","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0302","desc":"土蔵は主屋の西南に位置し，敷地南辺から西辺に回り込む石垣上に西壁を載せて建つ。桁行２間半，梁間２間，切妻造，本瓦葺の２階建土蔵で，東面中央に庇を出して戸口を設ける。外壁上部は白漆喰塗で，２階南妻面の窓廻りなどの凝った左官仕事に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005369"},{"id":"00005370","register_sub_id":"101","register_pk":"106358","name":"坂下勤家住宅納屋","kana":"さかしたつとむけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字坂ノ山甲258","lat":34.47605597,"lng":134.32197507,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0303","desc":"敷地東南部に南北棟で建つ。切妻造，桟瓦葺のつし２階建で，北妻面が主屋南面の東寄りに接続する。桁行６間，梁間２間規模で，敷地中央に面する西面と道路沿いの南面とに下屋庇を差し掛ける。土蔵，主屋とともに敷地中央の作業場空間をコの字形に囲む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005370"},{"id":"00002830","register_sub_id":"101","register_pk":"103820","name":"塩田家住宅北土蔵","kana":"しおだけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字石井甲140-2","lat":34.476334,"lng":134.319977,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0098","desc":"馬木川に架かる石橋から醸造場へ至る通路沿いに建つ。東西棟，本瓦葺，切妻造の２階建土蔵で，花崗石の切石積基礎の上に建ち，南面に戸前を設ける。住宅敷地の西北隅近くに位置し，東離屋方から回込んできた板塀とともに住宅部外周の構成要素ともなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002830"},{"id":"00003618","register_sub_id":"101","register_pk":"104608","name":"塩田家住宅主屋及び離れ座敷","kana":"しおたけじゅうたくしゅおくおよびはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字石井甲140-2","lat":34.476318,"lng":134.32014334,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積282㎡","structure_material":"木造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0175","desc":"馬木川沿いの住宅屋敷地の中央北寄りに主屋は東西棟で建つ。桁行１５ｍ梁行９ｍ規模の入母屋造，桟瓦葺で，庇を廻してつし２階風にみせ，南に玄関，北に釜屋を突き出し，西に南北棟の離れ座敷をつなげる。外装の腰上を黒漆喰で丁寧に仕上げた近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003618"},{"id":"00002827","register_sub_id":"101","register_pk":"103817","name":"塩田家住宅長屋門及び塀","kana":"しおだけじゅうたくながやもんおよびへい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字石井甲140-2","lat":34.47621273,"lng":134.3203691,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積35㎡、塀延長18m","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0095","desc":"醤油醸造場の南方住宅敷地の南辺に建つ。入母屋造，本瓦葺，腰を焼杉板張，上部を黒漆喰塗とした長屋門で，東に脇門，西に茶室を繋げる。塀は内側をコンクリート櫛目仕上，外側を縦板張とし，馬木川沿いは谷積石垣の上を源氏塀状として趣ある景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002827"},{"id":"00002829","register_sub_id":"101","register_pk":"103819","name":"塩田家住宅東離屋","kana":"しおだけじゅうたくひがしはなれや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字石井甲140-2","lat":34.47624467,"lng":134.319943,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0097","desc":"馬木川沿いに南土蔵と坪庭を隔てて北方に建つ。南北棟，本瓦葺，片入母屋造で，南北両妻面に下屋を差掛け，川沿いの西面北寄りには眉庇を付けて格子窓を設ける。もと「店」と伝える。土台は花崗石敷，腰は板張とし左右方の塀と一体的な景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002829"},{"id":"00002828","register_sub_id":"101","register_pk":"103818","name":"塩田家住宅南土蔵","kana":"しおだけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字石井甲140-2","lat":34.47616034,"lng":134.32001367,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0096","desc":"馬木川の屈曲部に位置し，西面は馬木川の石積護岸上に建つ。南北棟，本瓦葺，切妻造の土蔵で，北妻面に下屋を差掛けて蔵前を設ける。外部は塀よりも厚い花崗石土台，高い腰板張とし，板張と漆喰壁との境に水切瓦を入れるなど変化をもたせた外観としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002828"},{"id":"00003631","register_sub_id":"101","register_pk":"104621","name":"重田家住宅米蔵","kana":"しげたけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡まんのう町山脇字上平534","lat":34.12175634,"lng":133.82205431,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積84㎡、防火水槽付","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0188","desc":"主屋の東南方，主屋と長屋門間の広庭に西面して南北棟で建つ。桁行７間，梁間２間半規模，切妻造，桟瓦葺で，西面に下屋庇を差掛ける。内部は南から米蔵，納屋，道具入の３室とし，北妻面側には道具入の出入口脇に３ｍ×２ｍ規模の石積貯水槽を付属させる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003631"},{"id":"00003628","register_sub_id":"101","register_pk":"104618","name":"重田家住宅主屋","kana":"しげたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡まんのう町山脇字上平534","lat":34.12179283,"lng":133.82188328,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積158㎡、袖塀付","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0185","desc":"屋敷地中央北寄りに南面して建つ。桁行７間梁間５間規模，入母屋造，茅葺（鉄板仮葺）で，東方を下手とし，西方上手の南に６畳，８畳，８畳を配し，南西隅の８畳は仏間を兼ねた書院座敷とし西に入側縁を設ける。４周に庇を廻したいわゆる四方蓋農家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003628"},{"id":"00003630","register_sub_id":"101","register_pk":"104620","name":"重田家住宅道具蔵及び雪隠","kana":"しげたけじゅうたくどうぐぐらおよびせっちん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県仲多度郡まんのう町山脇字上平534","lat":34.12181652,"lng":133.82173438,"geo_status":"db","era":"明治10／大正3増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺、建築面積59㎡","structure_material":"土蔵造及び木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0187","desc":"主屋の西北隅に接続して東西棟で建ち，南面に下屋を差掛けて蔵前を取り，南西方に真壁造の雪隠を増築する。道具蔵は桁行５間梁間２間半規模，切妻造，桟瓦葺で，南面と北面の高い位置に２箇所づつの窓を開ける。屋敷地西北隅を構成する主要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003630"},{"id":"00003633","register_sub_id":"101","register_pk":"104623","name":"重田家住宅土塀及び石垣擁壁","kana":"しげたけじゅうたくどべいおよびいしがきようへき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡まんのう町山脇字上平534","lat":34.12147908,"lng":133.82194635,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土塀、延長40m、石造擁壁、延長50m","structure_material":"土塀","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0190","desc":"屋敷地西辺に築かれた高さ約１．５ｍの谷積石垣と高さ２ｍ規模の屋根付土塀と，屋敷地東辺の斜面に築かれた高さ２ｍの石垣から成る。石垣沿いには水路を廻らせており，長屋門や道具蔵とともに環濠屋敷を思わせる屋敷景観をつくりだす主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003633"},{"id":"00003632","register_sub_id":"101","register_pk":"104622","name":"重田家住宅取合廊下","kana":"しげたけじゅうたくとりあいろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県仲多度郡まんのう町山脇字上平534","lat":34.12166434,"lng":133.82191493,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0189","desc":"主屋座敷部と長屋門を結ぶ連絡廊下で，主屋南面の広庭を東方の作業場と西方の庭園とに分ける。廊下幅は半間，桁行長８間規模，真壁造で，白漆喰壁の上部に連子窓を開け，桟瓦葺の切妻屋根を架ける。廊下と庭塀を兼ね，農家としては稀な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003632"},{"id":"00003629","register_sub_id":"101","register_pk":"104619","name":"重田家住宅長屋門","kana":"しげたけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡まんのう町山脇字上平534","lat":34.12155752,"lng":133.82195928,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡、左右塀付","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0186","desc":"主屋南方に東西棟，入母屋造，桟瓦葺で建つ。桁行８間規模で，西方に８畳の座敷を配し，東寄りに門を開ける。外装は腰海鼠壁，上部黒漆喰塗とし，両脇に真壁造，瓦葺の木造塀を従える。通り沿い石垣水路との間に前庭をとり上層農家に相応しい佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003629"},{"id":"00004046","register_sub_id":"101","register_pk":"105036","name":"四国工芸社門","kana":"しこくこうげいしゃもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市豊浜町和田字直場甲334-25","lat":34.06881718,"lng":133.64379476,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3m、両脇袖塀付属","structure_material":"木造","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0211","desc":"丸亀藩主宿泊の際の御成門として建造と伝える。屋敷地東方に位置し，南北棟で建つ。反りをつけた切妻造，本瓦葺の四脚門で，懸魚や笈形の彫物，棟瓦などの凝った造りに特色がある。袖塀により前面に台形の広地を設けた豪壮な構えをとることも特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004046"},{"id":"00001751","register_sub_id":"101","register_pk":"102741","name":"四国村異人館ワサ・ダウン住宅","kana":"しこくむらいじんかんわさ・だうんじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県高松市屋島中町96","lat":34.344002,"lng":134.1086358,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0051","desc":"もと神戸市北野町に所在。いわゆる神戸の異人館で、木造２階建、寄棟造、桟瓦葺、下見板張のベランダ・コロニアル住宅。正面１階は吹放ちとするが、２階ベランダにはガラス戸を建て込む。建設年代的には明治後期であるが、明治中期異人館の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001751"},{"id":"00001752","register_sub_id":"101","register_pk":"102742","name":"四国村異人館ワサ・ダウン住宅正門","kana":"しこくむらいじんかんわさ・だうんじゅうたくせいもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市屋島中町96","lat":34.34394496,"lng":134.10854552,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"石造門柱、高さ2.2m、木製門扉付","structure_material":"石造門柱","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0052","desc":"神戸市北野町より住宅主屋とともに移築される。花崗石製の門柱に木製の両開き扉を開く。門柱は０．２５ｍ×０．２７ｍ、高さ２．２３ｍで、間口は１．５２ｍ。門柱間にアーチ型の鉄角棒で繋ぎ、その上に飾り金物を付けた文明開化調の意匠をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001752"},{"id":"00001753","register_sub_id":"101","register_pk":"102743","name":"四国村異人館ワサ・ダウン住宅東門","kana":"しこくむらいじんかんわさ・だうんじゅうたくひがしもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市屋島中町96","lat":34.34393072,"lng":134.108719,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"石造門柱、高さ2.2m、木製門扉付","structure_material":"石造門柱","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0053","desc":"神戸市北野町から住宅正門とともに移設される。花崗石製の門柱に片開きの室内戸に似た木製扉を開く。門柱は０．１８ｍ×０．２２ｍ、高さ２．２３ｍで、間口は０．９ｍとする。門柱、門柱間の繋ぎアーチとも正門よりも簡単なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001753"},{"id":"00001734","register_sub_id":"101","register_pk":"102724","name":"四国村稲田家住宅土蔵","kana":"しこくむらいなだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市屋島中町126-2","lat":34.3454028,"lng":134.1098228,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、茅葺、建築面積27㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0034","desc":"もと愛媛県上浮穴郡久万町上畑野川に所在した農家の道具蔵。木造２階建、置屋根形式の茅葺、妻入で、外壁は平側上部を除いて縦板張りとする。開口部の少ない、たちの高い土蔵で、交差組と叉首組とによる置屋根の架構に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001734"},{"id":"00001736","register_sub_id":"101","register_pk":"102726","name":"四国村久米通賢先生旧宅主屋","kana":"しこくむらくめみちたかせんせいきゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市屋島中町127","lat":34.344978,"lng":134.11026,"geo_status":"db","era":"19世紀","year":1850,"year_source":"estimated","year_min":1801,"year_max":1900,"year_label":"19世紀","structure":"木造平屋建、茅及び瓦葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0036","desc":"もと香川県大川郡引田町馬宿に所在した。江戸時代後期のオランダ流砲術家として知られる久米通賢の旧宅。寄棟造、茅葺の四周に本瓦葺の庇を回した「四方大蓋造り」と呼ばれる香川・徳島県に特徴的な民家の形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001736"},{"id":"00001729","register_sub_id":"101","register_pk":"102719","name":"四国村小豆島北浦村の石蔵","kana":"しこくむらしょうどしまきたうらむらのいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市屋島中町125","lat":34.34435448,"lng":134.10936072,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"石造平屋建、鉄板葺、建築面積5.3㎡","structure_material":"石造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0029","desc":"もと小豆郡土庄町北浦に所在。北浦出身で大阪に出て成功した藤原兵太郎が村に寄贈する公債類を保管するために建設したと伝えるユニークな金庫的建築。御影石の切石積で、刳型付きのコーニスを回し、正面に両開き鉄扉とムクリ破風状の鉄庇を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001729"},{"id":"00001730","register_sub_id":"101","register_pk":"102720","name":"四国村土佐三崎の義倉","kana":"しこくむらとさみさきのぎそう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市屋島中町125","lat":34.34447904,"lng":134.10930204,"geo_status":"db","era":"文政2","year":1819,"year_source":"db","year_min":1819,"year_max":1819,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0030","desc":"もと土佐清水市三崎に所在した。飢饉や災害に備える穀物蔵として地元の庄屋沖市左衛門が建てたと伝える。桁行６間梁行３間規模の切妻造の倉で、内部は２室に分かれ、正面平側に下屋庇を出して平入とする。外壁は縦板張りとし、内壁間柱には丸太材を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001730"},{"id":"00001731","register_sub_id":"101","register_pk":"102721","name":"四国村福井家の石蔵","kana":"しこくむらふくいけのいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市屋島中町125","lat":34.34456048,"lng":134.10938048,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造平屋建、瓦葺、建築面積72㎡","structure_material":"石造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0031","desc":"もと香川県綾歌郡国分寺町新名石舟の金毘羅街道沿いに所在。地元産の安山岩の長石を積んで壁体を造り、緩やかな勾配の本瓦葺寄棟屋根を架け、正面平側に本瓦葺の下屋庇を出して平入とする。近代的構法と伝統的手法が不思議と調和した建築になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001731"},{"id":"00001727","register_sub_id":"101","register_pk":"102717","name":"四国村前田家土蔵・座敷","kana":"しこくむらまえだけどぞう・ざしき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市屋島中町88","lat":34.34432769,"lng":134.10908745,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0027","desc":"もと高知市布師田に所在した。木造２階建、切妻造、桟瓦葺、置屋根形式の平入土蔵の平側に、６畳間を有する離れ座敷を接続する。土蔵の外周は、腰を海鼠壁とし、上部の漆喰壁面に高知地方特有の水切りのための瓦庇を３段ないし４段に付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001727"},{"id":"00001733","register_sub_id":"101","register_pk":"102723","name":"四国村森野家住宅風呂便所","kana":"しこくむらもりのけじゅうたくふろべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県高松市屋島中町126-6","lat":34.34552638,"lng":134.11027831,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積4.6㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0033","desc":"もと徳島県美馬郡脇町の農家に所在した。外風呂・外便所をひとつ屋根の下に並べたもので、切妻造、瓦葺で平入とする。正面左手の便所は下地窓をつけるなど数寄屋風の造りで、右手の風呂は土台を煉瓦積とし、妻面に焚き口を設け陶管の煙突を差し出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001733"},{"id":"00003146","register_sub_id":"101","register_pk":"104136","name":"島宿真里蔵","kana":"しまやどまりくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字糸鍬甲2011-1","lat":34.46651922,"lng":134.32339819,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0139","desc":"主屋の南方に東西棟で建つ。桁行３間梁間２間半規模，切妻造，本瓦葺の２階建土蔵で，北桁行面に入口を設ける。腰を杉板張り，上部を漆喰塗とし，境に水切瓦を四周に廻した丁寧なつくりになる。近年改修されて旅館の宿泊室として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003146"},{"id":"00003145","register_sub_id":"101","register_pk":"104135","name":"島宿真里主屋","kana":"しまやどまりしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字糸鍬甲2011-1","lat":34.46674005,"lng":134.3233059,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積92㎡、石垣付","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0138","desc":"内海湾苗羽港の東南方，碁石山の山裾に位置し，町道に面する低い石垣を廻した造成地に東西棟で建つ。もと大工の住宅で，桁行５間半梁間４間半規模とし，切妻屋根の北・西・南３面に下屋庇を廻しつし２階風に外観をつくる。旅館の食事室として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003145"},{"id":"00004673","register_sub_id":"101","register_pk":"105663","name":"正金醤油石井別邸","kana":"しょうきんしょうゆいしいべってい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字石井甲230-1","lat":34.47634527,"lng":134.32065579,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積56㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0265","desc":"醸造所敷地の東南方に位置し，東西棟で建つ。桁行１１ｍ梁行５ｍ規模，寄棟造，桟瓦葺の木造総２階建で，外部は縦板張とし，道路沿いの南面には上下階とも大きな開口部をとり，それぞれに庇をつける。隣接する醤油蔵と一体になり「醤の郷」景観の一翼を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004673"},{"id":"00004670","register_sub_id":"101","register_pk":"105660","name":"正金藤井家住宅主屋","kana":"しょうきんふじいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲813-1","lat":34.47548455,"lng":134.32065038,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0262","desc":"敷地東側道路沿いに流れる馬木川に東妻面を見せて東西棟で建つ。切妻造，本瓦葺の平屋建の四周に本瓦葺の下屋を廻した形式で，東方を土間とし，南面中央に玄関を置く。外部は黒漆喰塗で，軒や螻羽廻りを白漆喰塗で塗り込める。馬木川沿いで際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004670"},{"id":"00004672","register_sub_id":"101","register_pk":"105662","name":"正金藤井家住宅土蔵","kana":"しょうきんふじいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲813-1","lat":34.47538714,"lng":134.32065917,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0264","desc":"主屋と物置の間に南北棟で建つ。桁行２間半梁間２間，切妻造，本瓦葺，平入の２階建土蔵で，東面に本瓦葺の庇を差し掛けて戸口を設ける。外部は，腰焼杉縦板張，上部白漆喰塗で，境に水切，軒に鉢巻を廻した丁寧なつくり。屋敷構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004672"},{"id":"00004428","register_sub_id":"101","register_pk":"105418","name":"高橋家住宅主屋","kana":"たかはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.479069,"lng":134.315475,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0219","desc":"敷地中央にほぼ南面して建つ。木造平屋建，平入，屋根桟瓦葺で，中央の切妻造の４周に下屋庇を廻し，西妻面に角屋を突出する。いわゆる四方蓋造の民家で，平面も通り土間をもつ。古家を譲り受けたと伝えられ，改造もあるが，江戸末期の構造手法を残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004428"},{"id":"00002842","register_sub_id":"101","register_pk":"103832","name":"宝食品福井亭（旧福井家住宅土蔵）","kana":"たからしょくひんふくいてい（きゅうふくいけじゅうたくどぞう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町草壁本町615-26","lat":34.47845961,"lng":134.29976112,"geo_status":"db","era":"昭和10頃／平成5移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積21㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0110","desc":"内海町苗羽馬木地区所在の土蔵を草壁港近くに移築。桁行５ｍ，梁間４ｍ規模の本瓦葺，切妻造，平入土蔵で，基礎には角礫質凝灰岩の豊島石を用い，腰は杉板張，上部を白漆喰塗とし，入口上部に差掛の蔵前庇を付ける。現在は集会所として利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002842"},{"id":"00007601","register_sub_id":"101","register_pk":"108583","name":"滝口家住宅主屋","kana":"たきぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市鶴市町字御殿1595","lat":34.3294529,"lng":134.01249866,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"37 － 0320","desc":"南面して建つ木造つし２階建。入母屋造桟瓦葺で、周囲に下屋庇をまわし、西面に入母屋造の角屋を設ける。外壁は腰板張の聚楽壁で、つし２階部分を黒漆喰壁とする。東寄りに土間、西側は整形四間取に仏間を付設。牛梁と梁が数段に重なる土間梁組は見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007601"},{"id":"00005031","register_sub_id":"101","register_pk":"106021","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市屋島東町字相引1572-1","lat":34.34215421,"lng":134.113678,"geo_status":"db","era":"明治13頃","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積160㎡","structure_material":"木造平屋一部2階建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0277","desc":"東西方向に流れる相引川左岸沿いの一画に位置し，敷地の北寄りに南面して建つ。寄棟造のもと茅葺の屋根の四周に本瓦葺の下屋庇を廻した，いわゆる四方蓋造で，東方を土間，西方を六間取の床上部とする。屋島南麓の田園地帯の歴史的景観をつくる要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005031"},{"id":"00005032","register_sub_id":"101","register_pk":"106022","name":"田中家住宅酉蔵","kana":"たなかけじゅうたくとりぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市屋島東町字相引1572-1","lat":34.34208628,"lng":134.11354404,"geo_status":"db","era":"明治13頃","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0278","desc":"主屋の南西に位置し，南北棟で建つ。桁行５間，梁間２間半規模，切妻造，本瓦葺の２階建土蔵で，東面に半間の下屋を差し掛け，２箇所の戸口を開ける。南西端から南方，及び北西端から矩折れに北へ廻り込む瓦葺の土塀が延び，屋敷地西辺及び北辺の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005032"},{"id":"00005376","register_sub_id":"101","register_pk":"106364","name":"谷本家住宅主屋","kana":"たにもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市牟礼町牟礼字宗時2739-1","lat":34.35289393,"lng":134.12375066,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0296","desc":"五剣山西麓に位置する屋敷地中央に東西棟で建つ。入母屋造，本瓦葺，木造２階建で，１階四周に下屋を廻し，桁行１２．８ｍ，梁行８．９ｍの規模とする。建ちが高く，外部は白漆喰の塗込めとし，２階南北両面に虫籠窓を開け，四隅柱形に漆喰彫刻を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005376"},{"id":"00003323","register_sub_id":"101","register_pk":"104313","name":"天満屋呉服店米蔵","kana":"てんまやごふくてんこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市仏生山町字桜馬場甲542","lat":34.28019,"lng":134.047943,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積101㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0150","desc":"主屋東方，敷地の奥に建つ。桁行約１４ｍの土蔵造・２階建，南北棟の切妻造・本瓦葺で，漆喰塗の外壁を鉄板で保護している。主屋側の西面には戸口を設けて庇をつけ，２階の東西面には銅板扉付の窓を設ける。明治後期における商家の屋敷構成を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003323"},{"id":"00004439","register_sub_id":"101","register_pk":"105429","name":"徳山家住宅主屋","kana":"とくやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町2212","lat":34.30895443,"lng":133.82772512,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積219㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0230","desc":"市街を通る旧高松街道沿いに建つ。木造２階建，切妻造，本瓦葺，平入で，正面庇付，背後には新座敷がＬ字型に連続する。一部海鼠壁とした黒漆喰塗の外壁，出桁造で軒蛇腹を受けた２階軒など，重厚であるが，窓廻りはガラス戸を多用した近代的なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004439"},{"id":"00014098","register_sub_id":"101","register_pk":"508358","name":"鳥取家住宅裏座敷","kana":"とっとりけじゅうたくうらざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15275556,"lng":133.70617222,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0453","desc":"主屋の西側及び風呂場棟や比屋と渡廊下で接続して中庭に面する隠居屋で、のちに茶道教室に用いた。寄棟造桟瓦葺で南面濡縁で小舞打の軒を緩勾配で延ばす。内部は八畳二室で南室は畳床、部屋境と平書院に富士山の欄間を嵌める。造作丁寧な近代和風書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014098"},{"id":"00014095","register_sub_id":"101","register_pk":"508355","name":"鳥取家住宅主屋","kana":"とっとりけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15282222,"lng":133.70628889,"geo_status":"db","era":"明治前期／昭和中期・平成7年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺（鉄板仮葺）一部瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0450","desc":"三豊平野旧笠田村に所在する元村長宅。敷地中央に南面する寄棟造鉄板葺平入で、四周に下屋を廻らし瓦葺とする。東の土間を居間に改修、西の床上部は整形四間取平面で、八畳表座敷には押板床と仏壇を設ける。いわゆる四方蓋造の民家で地方色をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014095"},{"id":"00014104","register_sub_id":"101","register_pk":"508364","name":"鳥取家住宅温室","kana":"とっとりけじゅうたくおんしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15257778,"lng":133.70616111,"geo_status":"db","era":"昭和前期 ／平成19年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0459","desc":"敷地西辺南寄りに東面する、葵の栽培と小鳥の飼育のための細長い平面の建物。切妻造桟瓦葺で、外壁は真壁造中塗仕上で足元を洗出とする。小屋組は和小屋を現しとする。東面は開口が多く、扉とサッシュ窓を並べる。新座敷西の庭の背景となる珍しい建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014104"},{"id":"00014100","register_sub_id":"101","register_pk":"508360","name":"鳥取家住宅米蔵","kana":"とっとりけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15302222,"lng":133.70615556,"geo_status":"db","era":"明治27年／平成7年改修","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積72㎡","structure_material":"土蔵造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0455","desc":"敷地の北辺西半に建つ東西棟土蔵。平屋建の寄棟造桟瓦葺でもとは本瓦葺であった。軒は塗込めず、垂木は隅扇とする。外壁は白漆喰塗で、内壁も大壁とする。入口は木製ガラリ付板戸を建込む。和小屋の小屋梁に竹を組んで土を載せる。構法が特徴的な米蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014100"}];
